insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('beziakshauptmaunnschoft', 'Beziakshauptmaunnschoft', '', '', '', '', 'Bezirkshauptmannschaft', '[{"kategorie": "pol.", "text": "\"Verwaltungsbehörde auf regionaler Ebene in Österreich, die für die Vollziehung von [[Gesetzen]] und die Erbringung von Verwaltungsleistungen im jeweiligen Bezirk zuständig ist\""}, {"kategorie": "", "text": "Sie ist eine Landesbehörde, die im Auftrag der [[Landesregierung]] und teilweise auch im Auftrag des [[Bundes]] arbeitet"}, {"kategorie": "", "text": "Die Bezirkshauptmannschaft übernimmt zahlreiche Verwaltungsaufgaben, die sowohl aus der Bundes- als auch aus der Landesgesetzgebung stammen. Dazu zählen unter anderem die Ausstellung von Dokumenten (z. B. Reisepässen), das Meldewesen und die Verwaltung von Sozialhilfemaßnahmen"}, {"kategorie": "", "text": "Die Behörde ist auch für die öffentliche Sicherheit im Bezirk zuständig. Dies umfasst Aufgaben wie den Katastrophenschutz, die Polizeiaufsicht und den Verkehrsbereich (z. B. Kfz-Zulassungen)"}, {"kategorie": "", "text": "Die Bezirkshauptmannschaft erteilt Baugenehmigungen, Gewerbeberechtigungen und andere [[Bescheide]], die für Bürger und Unternehmen im Bezirk relevant sind"}, {"kategorie": "", "text": "Die Bezirkshauptmannschaft spielt auch eine Rolle im Gesundheitsbereich, z. B. bei der Überwachung von Hygienevorschriften und der Erteilung von Gesundheitszeugnissen"}, {"kategorie": "", "text": "Eine Bezirkshauptmannschaft wird von einem [[Bezirkshauptmann]] geleitet, der die Behörde verwaltet und die staatlichen Aufgaben auf Bezirksebene koordiniert"}, {"kategorie": "", "text": "Es gibt mehrere Abteilungen innerhalb der Bezirkshauptmannschaft, die für unterschiedliche Zuständigkeitsbereiche verantwortlich sind, wie z. B. die Bauabteilung, die Gesundheitsabteilung oder die Sicherheitsabteilung"}, {"kategorie": "", "text": "Bezirkshauptmannschaften sind wesentliche Institutionen in der föderalen Struktur Österreichs, da sie sowohl Aufgaben des Landes als auch des Bundes umsetzen. Sie dienen als Bindeglied zwischen den Bürgern und der staatlichen Verwaltung und stellen sicher, dass Gesetze und Verordnungen effektiv auf regionaler Ebene angewendet werden."}]'::jsonb, ''),
  ('vawoitungsbehoeadn', 'Vawoitungsbehöadn', '', '', '', '', 'Verwaltungsbehörden', '[{"kategorie": "pol.", "text": "\"staatliche Institution oder Einrichtung, die für die Durchführung und Umsetzung von Gesetzen sowie für die Verwaltung von öffentlichen Angelegenheiten zuständig ist\""}, {"kategorie": "", "text": "Sie gehört zur [[Exekutive]] und agiert auf Bundes-, Landes- und Gemeindeebene, um gesetzliche Bestimmungen in die Praxis umzusetzen"}, {"kategorie": "", "text": "Verwaltungsbehörden handeln innerhalb der von der [[Legislative]] (z. B. [[Nationalrat]]) festgelegten [[Gesetze]] und können durch [[Verordnungen]] und [[Bescheide]] die Rechte und Pflichten der Bürger konkretisieren"}, {"kategorie": "", "text": "Arten von Verwaltungsbehörden in Österreich:\n(i) Bundesbehörden: Diese sind für die Durchführung von [[Bundesgesetzen]] zuständig. Dazu zählen die Ministerien (z. B. das Bundesministerium für Finanzen), die als oberste Verwaltungsbehörden fungieren, sowie untergeordnete Behörden wie Finanzämter oder Bundespolizeidirektionen;  (ii) Landesbehörden: Auf Länderebene übernehmen [[Landesregierungen]] und deren nachgeordnete Behörden (z. B. [[Bezirkshauptmannschaften]]) die Vollziehung der Landesgesetze und auch der Bundesgesetze, soweit sie nicht direkt vom [[Bund]] vollzogen werden;  (iii) Gemeindebehörden: In den Gemeinden sind die Gemeindeämter oder der Bürgermeister für die Vollziehung von Aufgaben der örtlichen Verwaltung verantwortlich. Sie setzen sowohl Gemeindeverordnungen als auch delegierte Aufgaben aus Bundes- und Landesgesetzen um"}, {"kategorie": "", "text": "Verwaltungsbehörden sorgen dafür, dass die gesetzlichen Vorschriften auf allen staatlichen Ebenen eingehalten und umgesetzt werden. Dazu gehört beispielsweise die Ausstellung von Dokumenten (z. B. Reisepässe, Baugenehmigungen), die Einhebung von Steuern oder die Überwachung der öffentlichen Sicherheit"}, {"kategorie": "", "text": "Verwaltungsbehörden können innerhalb ihres Zuständigkeitsbereichs [[Verordnungen]] erlassen, die bestimmte gesetzliche Bestimmungen konkretisieren"}, {"kategorie": "", "text": "Verwaltungsbehörden entscheiden in Einzelfällen durch [[Bescheide]], die für den Bürger verbindlich sind, z. B. in Fragen von Sozialhilfe, Bauangelegenheiten oder Strafsachen."}]'::jsonb, ''),
  ('vaoadnung', 'Vaoadnung', '', '', '', '', 'Verordnung', '[{"kategorie": "pol.", "text": "\"Rechtsnorm, die von [[Verwaltungsbehörden]] (z. B. [[Ministerien]], [[Landesregierungen]] oder [[Bezirksverwaltungsbehörden]]) erlassen wird und zur Konkretisierung von [[Gesetzen]] dient\""}, {"kategorie": "", "text": "Verordnungen haben dieselbe rechtliche Verbindlichkeit wie Gesetze, sind jedoch keine eigenständigen Gesetzgebungsakte, sondern dienen der Umsetzung und Anwendung von bestehenden Gesetzen"}, {"kategorie": "", "text": "Verordnungen werden von Exekutivorganen erlassen, die durch ein Gesetz dazu ermächtigt wurden. Die Regierung (z. B. ein Ministerium) hat die Befugnis, Verordnungen zu erlassen, um die Details und Bestimmungen eines Gesetzes näher zu regeln"}, {"kategorie": "", "text": "Während Gesetze oft allgemeine Rahmenvorschriften enthalten, regeln Verordnungen die konkreten Details der Anwendung. Sie legen fest, wie ein Gesetz in der Praxis umgesetzt wird. Beispielsweise kann ein Gesetz ein allgemeines Ziel wie den Umweltschutz festlegen, während eine Verordnung genaue Grenzwerte oder Maßnahmen definiert"}, {"kategorie": "", "text": "Verordnungen haben rechtlich bindende Wirkung und müssen von Bürgern und Behörden eingehalten werden. Sie treten in der Regel nach ihrer Veröffentlichung im [[Bundesgesetzblatt]] in Kraft"}, {"kategorie": "", "text": "Verordnungen können in vielen Bereichen erlassen werden, wie z. B. im Gesundheitswesen (z. B. Quarantänebestimmungen), im Straßenverkehr (z. B. Geschwindigkeitsbegrenzungen) oder im Arbeitsrecht (z. B. Regelungen zu Arbeitssicherheit)"}, {"kategorie": "", "text": "Verordnungen werden nicht vom Parlament (Nationalrat) beschlossen, sondern von Verwaltungsorganen erlassen. Sie dürfen jedoch nur im Rahmen der bestehenden Gesetze erlassen werden und sind diesen untergeordnet. Gesetze schaffen den Rahmen, während Verordnungen diesen Rahmen ausfüllen und spezifische Regelungen treffen"}, {"kategorie": "", "text": "Verordnungen sind also ein wichtiges Instrument der Exekutive in Österreich, um Gesetze im Detail anwendbar zu machen und die Verwaltungspraxis zu regeln"}]'::jsonb, ''),
  ('bundesgesetz', 'Bundesgesetz', '', '', '', '', 'Bundesgesetz', '[{"kategorie": "pol.", "text": "\"Gesetz, das von der Bundesebene ausgeht und für das gesamte Staatsgebiet gültig ist\""}, {"kategorie": "", "text": "Es wird im [[Nationalrat]] beschlossen, dem österreichischen [[Parlament]], und regelt rechtliche Angelegenheiten, die in den Kompetenzbereich des [[Bundes]] fallen"}, {"kategorie": "", "text": "Die Verabschiedung von Bundesgesetzen erfolgt im Rahmen des [[Gesetzgebungsverfahrens]], das verschiedene Schritte durchläuft, bevor ein Gesetz in Kraft treten kann"}, {"kategorie": "", "text": "Bundesgesetze werden vom Nationalrat verabschiedet, wobei der Gesetzgebungsprozess mehrere Stufen umfasst: (i) Einbringung eines [[Gesetzesvorschlags]] (z. B. durch die [[Bundesregierung]], [[Abgeordnete]] oder durch [[Volksbegehren]]);  (ii) Beratung und Abstimmung im Nationalrat;  (iii) Zustimmung oder Ablehnung durch den [[Bundesrat]];  (iv) Unterzeichnung durch den [[Bundespräsidenten]];  (v) Veröffentlichung im [[Bundesgesetzblatt]], wodurch das Gesetz rechtskräftig wird"}, {"kategorie": "", "text": "Bundesgesetze müssen im Einklang mit der österreichischen [[Bundesverfassung]] stehen. Es gibt besondere Anforderungen für [[Verfassungsgesetze]], die eine qualifizierte Mehrheit im Parlament erfordern"}, {"kategorie": "", "text": "Beispiele für Bundesgesetze: (i) Strafgesetzbuch (StGB - regelt das Strafrecht in Österreich),  (ii) Einkommensteuergesetz (bestimmt die Besteuerung von Einkommen),  (iii) Allgemeines Bürgerliches Gesetzbuch (ABGB - ein zentrales Regelwerk des Zivilrechts in Österreich)"}, {"kategorie": "", "text": "Bundesgesetze sind somit ein wesentlicher Bestandteil des österreichischen [[Rechtsstaats]], die das Funktionieren des Staates und das Leben der Bürger in klar definierten Bereichen regeln​."}]'::jsonb, ''),
  ('gesetz', 'Gesetz', '', '', '', '', 'Gesetz', '[{"kategorie": "pol.", "text": "\"allgemein verbindliche Regelung, die von der gesetzgebenden Gewalt ([[Legislative]]) erlassen wird\""}, {"kategorie": "", "text": "Gesetze dienen dazu, das Zusammenleben der Gesellschaft zu regeln, Rechte und Pflichten zu definieren und das Handeln von Staat und Bürgern zu steuern"}, {"kategorie": "", "text": "Sie werden nach einem festgelegten [[Gesetzgebungsverfahren]] verabschiedet, das den [[Nationalrat]], den [[Bundesrat]] und den [[Bundespräsidenten]] umfasst"}, {"kategorie": "", "text": "Gesetze werden in einem mehrstufigen Verfahren vom Nationalrat (dem [[Parlament]]) beschlossen. Sie können von der [[Bundesregierung]], einzelnen [[Abgeordneten]] oder durch [[Volksbegehren]] initiiert werden"}, {"kategorie": "", "text": "Ein Gesetz hat eine verbindliche Wirkung für alle Bürger, Institutionen und staatlichen Organe. Es regelt, was erlaubt oder verboten ist, und legt die entsprechenden Konsequenzen fest"}, {"kategorie": "", "text": "Es gibt unterschiedliche Arten von Gesetzen: (i) Verfassungsgesetze (diese bilden das Fundament der staatlichen Ordnung und stehen über den einfachen Gesetzen. Sie regeln grundlegende Prinzipien wie die Gewaltenteilung, Grundrechte oder die Organisation des Staates),  (ii) einfache Gesetze (diese regeln spezifische Sachbereiche, wie z. B. das Strafrecht, Arbeitsrecht oder Verkehrsrecht, und bauen auf den Verfassungsgrundlagen auf)"}, {"kategorie": "", "text": "Nach der Verabschiedung durch den [[Nationalrat]] und der Zustimmung des [[Bundesrats]] wird ein Gesetz vom [[Bundespräsidenten]] unterzeichnet und anschließend im [[Bundesgesetzblatt]] veröffentlicht. Erst mit der Veröffentlichung tritt es in Kraft"}, {"kategorie": "", "text": "Gesetze sollen Rechtsklarheit schaffen und das friedliche Zusammenleben in einer Gesellschaft sichern. Sie legen Rechte und Pflichten fest, steuern die staatliche Verwaltung und bieten eine Grundlage für die Rechtsprechung. Gesetze sind damit zentrale Instrumente der staatlichen Ordnung und der Durchsetzung des Rechtsstaates​."}]'::jsonb, ''),
  ('gesetzgebungsprozess', 'Gesetzgebungsprozess', '', '', '', '', 'Gesetzgebungsprozess', '[{"kategorie": "pol.", "text": "\"Prozess, durch den neue [[Gesetze]] geschaffen oder bestehende Gesetze geändert werden\""}, {"kategorie": "", "text": "Es folgt einem strukturierten Ablauf, der mehrere Instanzen der politischen Entscheidungsfindung durchläuft, bevor ein Gesetz in Kraft treten kann"}, {"kategorie": "", "text": "Der [[Nationalrat]] spielt dabei eine zentrale Rolle, und der Prozess beinhaltet mehrere Schritte der Beratung, Beschlussfassung und Prüfung"}, {"kategorie": "", "text": "Ablauf des Gesetzgebungsverfahrens in Österreich: (i) Initiative: ein Gesetzesvorschlag, d.h. eine [[Gesetzesvorlage]], kann von verschiedenen Akteuren eingebracht werden, darunter: Bundesregierung ([[Regierungsvorlagen]]), [[Abgeordnete]] des Nationalrats ([[Initiativanträge]]), [[Bundesrat]] (Länderkammer) oder\nüber ein [[Volksbegehren]];  (ii) Erste Lesung im Nationalrat: Die Gesetzesvorlage wird zunächst im Nationalrat (dem [[Parlament]]) eingebracht und in der ersten Lesung grundsätzlich diskutiert. Hierbei wird entschieden, ob die Vorlage in die [[Fachausschüsse]] überwiesen wird;  (iii) Ausschussberatung: In einem [[Fachausschuss]] des Nationalrats wird die Vorlage im Detail geprüft, oft unter Hinzuziehung von Experten. Der Ausschuss erarbeitet einen Bericht und empfiehlt dem Nationalrat eine Annahme, Ablehnung oder Änderung des Gesetzes;  (iv) Zweite Lesung: In der zweiten Lesung im Nationalrat wird der Gesetzesentwurf erneut diskutiert, diesmal detailliert. Änderungen, die der Ausschuss vorgeschlagen hat, werden erörtert;  (v) Dritte Lesung und Abstimmung: In der dritten Lesung wird abschließend über den [[Gesetzesentwurf]] abgestimmt. Wenn eine Mehrheit der Abgeordneten zustimmt, gilt das Gesetz als beschlossen;  (vi) Prüfung durch den [[Bundesrat]]: Nach der Annahme durch den Nationalrat wird der Gesetzesbeschluss dem Bundesrat vorgelegt. Der Bundesrat hat das Recht, ein aufschiebendes Veto einzulegen. Ein Veto kann durch den Nationalrat überstimmt werden;  (vii) Beglaubigung durch den [[Bundespräsidenten]]: Nach Zustimmung des Bundesrats oder der Überstimmung des Vetos im Nationalrat wird das Gesetz dem Bundespräsidenten zur Unterzeichnung vorgelegt. Der Bundespräsident prüft das Gesetz formell und unterzeichnet es;  (viii) Verkündung und Inkrafttreten: Nach der Unterzeichnung durch den Bundespräsidenten wird das Gesetz im [[Bundesgesetzblatt]] veröffentlicht und tritt zu einem festgelegten Zeitpunkt in Kraft."}]'::jsonb, ''),
  ('gesetzgebungsvafoan', 'Gesetzgebungsvafoan', '', '', '', '', 'Gesetzgebungsverfahren', '[{"kategorie": "pol.", "text": "\"Prozess, durch den neue [[Gesetze]] geschaffen oder bestehende Gesetze geändert werden\""}, {"kategorie": "", "text": "Es folgt einem strukturierten Ablauf, der mehrere Instanzen der politischen Entscheidungsfindung durchläuft, bevor ein Gesetz in Kraft treten kann"}, {"kategorie": "", "text": "Der [[Nationalrat]] spielt dabei eine zentrale Rolle, und der Prozess beinhaltet mehrere Schritte der Beratung, Beschlussfassung und Prüfung"}, {"kategorie": "", "text": "Ablauf des Gesetzgebungsverfahrens in Österreich: (i) Initiative: ein Gesetzesvorschlag, d.h. eine [[Gesetzesvorlage]], kann von verschiedenen Akteuren eingebracht werden, darunter: Bundesregierung ([[Regierungsvorlagen]]), [[Abgeordnete]] des Nationalrats ([[Initiativanträge]]), [[Bundesrat]] (Länderkammer) oder\nüber ein [[Volksbegehren]];  (ii) Erste Lesung im Nationalrat: Die Gesetzesvorlage wird zunächst im Nationalrat (dem [[Parlament]]) eingebracht und in der ersten Lesung grundsätzlich diskutiert. Hierbei wird entschieden, ob die Vorlage in die [[Fachausschüsse]] überwiesen wird;  (iii) Ausschussberatung: In einem [[Fachausschuss]] des Nationalrats wird die Vorlage im Detail geprüft, oft unter Hinzuziehung von Experten. Der Ausschuss erarbeitet einen Bericht und empfiehlt dem Nationalrat eine Annahme, Ablehnung oder Änderung des Gesetzes;  (iv) Zweite Lesung: In der zweiten Lesung im Nationalrat wird der Gesetzesentwurf erneut diskutiert, diesmal detailliert. Änderungen, die der Ausschuss vorgeschlagen hat, werden erörtert;  (v) Dritte Lesung und Abstimmung: In der dritten Lesung wird abschließend über den [[Gesetzesentwurf]] abgestimmt. Wenn eine Mehrheit der Abgeordneten zustimmt, gilt das Gesetz als beschlossen;  (vi) Prüfung durch den [[Bundesrat]]: Nach der Annahme durch den Nationalrat wird der Gesetzesbeschluss dem Bundesrat vorgelegt. Der Bundesrat hat das Recht, ein aufschiebendes Veto einzulegen. Ein Veto kann durch den Nationalrat überstimmt werden;  (vii) Beglaubigung durch den [[Bundespräsidenten]]: Nach Zustimmung des Bundesrats oder der Überstimmung des Vetos im Nationalrat wird das Gesetz dem Bundespräsidenten zur Unterzeichnung vorgelegt. Der Bundespräsident prüft das Gesetz formell und unterzeichnet es;  (viii) Verkündung und Inkrafttreten: Nach der Unterzeichnung durch den Bundespräsidenten wird das Gesetz im [[Bundesgesetzblatt]] veröffentlicht und tritt zu einem festgelegten Zeitpunkt in Kraft."}]'::jsonb, ''),
  ('gesetzesvoalooge', 'Gesetzesvoalooge', '', '', '', '', 'Gesetzesvorlage', '[{"kategorie": "pol.", "text": "\"formeller Entwurf für ein neues Gesetz oder eine Änderung eines bestehenden Gesetzes, der dem [[Nationalrat]] zur Abstimmung vorgelegt wird\""}, {"kategorie": "", "text": "Sie bildet den ersten Schritt im [[Gesetzgebungsverfahren]], das mit der Beratung und Abstimmung im [[Parlament]] beginnt und schließlich zur Umsetzung in der Praxis führen kann"}, {"kategorie": "", "text": "Eine Gesetzesvorlage kann von der Bundesregierung (als sogenannte [[Regierungsvorlage]]), von den [[Abgeordneten]] des Nationalrats (Initiativanträge), von Mitgliedern des [[Bundesrats]] oder durch [[Volksbegehren]] eingebracht werden"}, {"kategorie": "", "text": "Die Gesetzesvorlage wird im Nationalrat in drei [[Lesungen]] behandelt. In diesen Lesungen wird der Entwurf diskutiert, Änderungen vorgeschlagen und schließlich darüber abgestimmt"}, {"kategorie": "", "text": "Nach der Beratung und gegebenenfalls Änderungen erfolgt die Abstimmung im Nationalrat. Bei einer Mehrheit wird die Gesetzesvorlage angenommen"}, {"kategorie": "", "text": "Nach der Annahme im Nationalrat wird die Gesetzesvorlage dem Bundesrat zur Zustimmung übermittelt. In seltenen Fällen kann der Bundesrat ein Veto einlegen"}, {"kategorie": "", "text": "Abschließend muss das Gesetz vom [[Bundespräsidenten]] unterzeichnet werden, bevor es veröffentlicht und rechtskräftig wird"}, {"kategorie": "", "text": "In Österreich sind [[Regierungsvorlagen]] die häufigste Form von Gesetzesvorlagen, da die [[Bundesregierung]] oft die politische Initiative für gesetzliche Änderungen übernimmt​"}]'::jsonb, ''),
  ('besotzungszonan', 'Besotzungszonan', '', '', '', '', 'Besatzungszonen', '[{"kategorie": "allg.", "text": "\"besetzte Gebiete Wiens, die nach dem Ende des [[Zweiten]] Weltkriegs von 1945 bis zur Unterzeichnung des [[Staatsvertrags]] 1955 von den Alliierten Mächten USA, Sowjetunion, Großbritannien und Frankreich kontrolliert wurden\""}, {"kategorie": "", "text": "Diese Aufteilung betraf das gesamte Wiener Stadtgebiet, wobei jede Besatzungsmacht eine eigene Zone verwaltete"}, {"kategorie": "", "text": "Die Verwaltung des 1. Bezirks ([[Innere]] Stadt) erfolgte durch alle vier Mächte gemeinsam und wurde als \"internationale Zone bezeichnet\""}, {"kategorie": "", "text": "Die Besatzungszonen waren unter den [[Alliierten]] wie folgt aufgeteilt: (i) Die USA verwalteten die Stadtbezirke 7., 8., 9., 17., 18. und 19;  (ii) Die Sowjetunion kontrollierte die Stadtbezirke 2., 4., 10., 20. sowie den 21. Bezirk;  (iii) Großbritannien erhielt die Stadtbezirke 3., 5., 11. und 12;  (iv) Frankreich verwaltete die Stadtbezirke 6., 14., 15. und 16"}, {"kategorie": "", "text": "Trotz dieser Besatzung blieb die Verwaltung der Stadt auf lokaler Ebene teilweise bestehen."}]'::jsonb, ''),
  ('mittlmaechte', 'Mittlmächte', '', '', '', '', 'Mittelmächte', '[{"kategorie": "allg.", "text": "\"Bündnis im Ersten Weltkrieg (1914–1918), bestehend aus Deutschland, Österreich-Ungarn, dem Osmanischen Reich und Bulgarien\""}, {"kategorie": "", "text": "Die Mittelmächte kämpften gegen die Alliierten, zu denen unter anderem Frankreich, Großbritannien, Russland und später die USA gehörten"}, {"kategorie": "", "text": "Die Bezeichnung \"Mittelmächte\" stammt von der geografischen Lage Deutschlands und Österreich-Ungarns in Mitteleuropa"}, {"kategorie": "", "text": "Nach anfänglichen Erfolgen erlitten die Mittelmächte schließlich schwere Niederlagen, was zum Zerfall von [[Österreich-Ungarn]] und dem Osmanischen Reich sowie zur deutschen Kapitulation führte."}]'::jsonb, ''),
  ('auschluss', 'Auschluss', '', '', '', '', 'Anschluss', '[{"kategorie": "allg.", "text": "\"erzwungene Eingliederung Österreichs in das nationalsozialistische Deutschland am 12. März 1938\""}, {"kategorie": "", "text": "Dieser Schritt markierte das Ende der [[Ersten]] Republik Österreich, der mit dem Einmarsch deutscher Truppen begann, gefolgt von einer manipulierten Volksabstimmung am 10. April 1938, bei der die Annexion offiziell bestätigt wurde"}, {"kategorie": "", "text": "Der Anschluss führte zur Eingliederung Österreichs als \"Ostmark\" in das [[Dritte]] Reich und hatte weitreichende politische und soziale Folgen, insbesondere für jüdische Bürger und politische Gegner des NS-Regimes"}, {"kategorie": "", "text": "Nach dem Ende des [[Zweiten]] Weltkriegs und der Befreiung Österreichs durch die Alliierten im Jahr 1945 wurde der Anschluss von der internationalen Gemeinschaft für illegal erklärt, und Österreich wurde wieder zu einem unabhängigen Staat."}]'::jsonb, ''),
  ('schdammasduaf', 'Schdammasduaf', '', '', '', '', 'Stammersdorf', '[{"kategorie": "allg.", "text": "\"Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), der für seine historische Architektur, seinen ländlichen Charakter und seine lange Weinbautradition bekannt ist\""}, {"kategorie": "", "text": "Das Herz des Ortes bildet die [[Pfarrkirche]] Stammersdorf, eine barocke Kirche aus dem 18. Jahrhundert, die sich durch ihren markanten Zwiebelturm auszeichnet. Die Kirche steht auf einem Hügel und bietet einen malerischen Ausblick über die Weinberge und den [[Bisamberg]]"}, {"kategorie": "", "text": "Ein architektonisches Highlight sind die [[Kellergassen]], typische Weinlagerstraßen, die das Bild des Ortes prägen"}, {"kategorie": "", "text": "Die Stammersdorfer Kellergasse ist eine der bekanntesten und zählt zu den schönsten Kellergassen Wiens. Hier befinden sich viele traditionelle [[Heurige]], wo der lokale Wein ausgeschenkt wird, und die das Zentrum des gesellschaftlichen Lebens in Stammersdorf bilden. Besonders im Herbst, zur Zeit der Weinlese, ist die Gegend ein beliebtes Ausflugsziel für Spaziergänger und Weinliebhaber"}, {"kategorie": "", "text": "Stammersdorf bietet eine einzigartige Mischung aus Geschichte, Natur, Architektur und [[Wiener]] Tradition und hat sich dabei trotz der Eingliederung in die Großstadt Wien seinen ursprünglichen, dörflichen Charakter bewahrt."}]'::jsonb, ''),
  ('bisambeag', 'Bisambeag', '', '', '', '', 'Bisamberg', '[{"kategorie": "allg.", "text": "\"markanter Hügel im Norden Wiens mit einer Höhe von etwa 358 Metern, der sich über die Wiener Stadtgrenze bis in das südliche Niederösterreich erstreckt\""}, {"kategorie": "", "text": "Der Bisamberg ist auch Teil der [[Wiener]] Pforte (Donaudurchbruch zwischen dem Bisamberg und dem [[Leopoldsberg]], wo die Donau von Norden ins Wiener Stadtgebiet fließt)"}, {"kategorie": "", "text": "Während der [[napoleonischen]] Kriege und im [[Zweiten]] Weltkrieg spielte der Bisamberg aufgrund seiner strategischen Lage eine wichtige Rolle. In der Nähe des Hügels wurden während des Krieges Flugabwehrstellungen errichtet, und er diente als strategischer Aussichtspunkt"}, {"kategorie": "", "text": "Der Bisamberg bietet eine Vielzahl von Wanderwegen durch Weinberge und Wälder sowie eine beeindruckende Aussicht auf Wien und die [[Donau]].   Der Hügel hat eine reiche Flora und Fauna und ist ein bedeutendes Naturschutzgebiet"}, {"kategorie": "", "text": "Die Region ist auch für den Weinbau bekannt, und rund um den Bisamberg befinden sich eine Vielzahl von [[Heurigenlokalen]]"}, {"kategorie": "", "text": "Am Fuße des Bisambergs liegt auch der beliebte Heurigenort [[Stammersdorf]], der für seine malerischen [[Kellergassen]], typische Weinlagerstraßen, weit über die Wiener Stadtgrenzen hinweg bekannt ist."}]'::jsonb, ''),
  ('vakeasmuseum', 'Vakeasmuseum', '', '', '', '', 'Verkehrsmuseum', '[{"kategorie": "allg.", "text": "\"Verkehrsmuseum Remise\" (offiziell bekannt als \"Verkehrsmuseum der [[Wiener]] Linien\"), befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]), genauer gesagt in der ehemaligen Straßenbahn-Remise [[Erdberg]]"}, {"kategorie": "", "text": "Das Museum widmet sich der Geschichte und Entwicklung des öffentlichen Nahverkehrs in Wien und ist eines der wichtigsten Museen in Österreich, das sich speziell mit diesem Thema befasst"}, {"kategorie": "", "text": "Es wurde 2014 nach umfangreichen Renovierungsarbeiten in einer historischen Remise eröffnet, die ursprünglich im Jahr 1901 erbaut wurde"}, {"kategorie": "", "text": "Das Museum beherbergt eine beeindruckende Sammlung von historischen Fahrzeugen, darunter Straßenbahnen, Busse, U-Bahn-Wagen und Spezialfahrzeuge. Diese Exponate reichen von der ersten Pferdestraßenbahn, die in Wien ab 1865 im Einsatz war, bis hin zu modernen Fahrzeugen der Wiener Linien. Die Fahrzeuge sind sorgfältig restauriert und vermitteln einen detaillierten Eindruck davon, wie sich der öffentliche Nahverkehr im Laufe der Zeit verändert hat"}, {"kategorie": "", "text": "Ein besonderes Highlight sind die sogenannten \"Ringstraßenbahnen\", historische Straßenbahnmodelle, die einst die berühmte Wiener Ringstraße bedienten, sowie die frühen elektrischen Straßenbahnen, die ab dem späten 19. Jahrhundert den Verkehr revolutionierten."}]'::jsonb, ''),
  ('schdrossnbaunmuseum', 'Schdrossnbaunmuseum', '', '', '', '', 'Straßenbahnmuseum', '[{"kategorie": "offiziell bekannt als", "text": "\"Verkehrsmuseum Remise\" bzw. \"Verkehrsmuseum der [[Wiener]] Linien\", befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]), genauer gesagt in der ehemaligen Straßenbahn-Remise [[Erdberg]]"}, {"kategorie": "", "text": "Das Museum widmet sich der Geschichte und Entwicklung des öffentlichen Nahverkehrs in Wien und ist eines der wichtigsten Museen in Österreich, das sich speziell mit diesem Thema befasst"}, {"kategorie": "", "text": "Es wurde 2014 nach umfangreichen Renovierungsarbeiten in einer historischen Remise eröffnet, die ursprünglich im Jahr 1901 erbaut wurde"}, {"kategorie": "", "text": "Das Museum beherbergt eine beeindruckende Sammlung von historischen Fahrzeugen, darunter Straßenbahnen, Busse, U-Bahn-Wagen und Spezialfahrzeuge. Diese Exponate reichen von der ersten Pferdestraßenbahn, die in Wien ab 1865 im Einsatz war, bis hin zu modernen Fahrzeugen der Wiener Linien. Die Fahrzeuge sind sorgfältig restauriert und vermitteln einen detaillierten Eindruck davon, wie sich der öffentliche Nahverkehr im Laufe der Zeit verändert hat"}, {"kategorie": "", "text": "Ein besonderes Highlight sind die sogenannten \"Ringstraßenbahnen\", historische Straßenbahnmodelle, die einst die berühmte Wiener Ringstraße bedienten, sowie die frühen elektrischen Straßenbahnen, die ab dem späten 19. Jahrhundert den Verkehr revolutionierten."}]'::jsonb, ''),
  ('foeschamuseum', 'Föschamuseum', '', '', '', '', 'Fälschermuseum', '[{"kategorie": "allg.", "text": "\"einzigartiges Museum, das sich auf die Ausstellung und Dokumentation von Kunstfälschungen und den damit verbundenen Geschichten spezialisiert hat\""}, {"kategorie": "", "text": "Es befindet sich im 3. Wiener Gemeindebezirk ([[Landstraße]]), gleich vis-[[-vis]] vom [[Hundertwasserhaus]], in der [[Löwengasse]] 28"}, {"kategorie": "", "text": "Das Museum wurde 2005 gegründet und widmet sich der faszinierenden und oft mysteriösen Welt der Kunstfälschungen, Fälscher und Fälschungsermittlungen"}, {"kategorie": "", "text": "Im Fälschermuseum werden vor allem Reproduktionen berühmter Fälschungen sowie die Werke bekannter Kunstfälscher ausgestellt. Einige der bekanntesten Fälscher, deren Arbeiten hier gezeigt werden, sind Han van Meegeren, der für seine gefälschten Vermeer-Gemälde berühmt wurde, sowie Tom Keating und Konrad Kujau, der durch die gefälschten \"Hitler-Tagebücher\" weltweit bekannt wurde"}, {"kategorie": "", "text": "Die ausgestellten Kunstwerke sind oft täuschend echt und veranschaulichen die technischen Fertigkeiten der Fälscher, die es geschafft haben, die Kunstwelt zu täuschen."}]'::jsonb, ''),
  ('loewngossn', 'Löwngossn', '', '', '', '', 'Löwengasse', '[{"kategorie": "allg.", "text": "belebte Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])"}, {"kategorie": "", "text": "Sie erstreckt sich vom [[Radetzkyplatz]] in der Nähe des Donaukanals bis zur [[Erdbergstraße]] und ist historisch und kulturell bedeutsam"}, {"kategorie": "", "text": "Der Name der Löwengasse stammt von einem ehemaligen Hausschild namens \"Zum goldenen Löwen\", das sich früher an der Adresse Löwengasse 29 befand (bereits 1765 erwähnt)"}, {"kategorie": "", "text": "Die Löwengasse liegt in einem charmanten, zentralen Stadtteil Wiens, der sowohl von historischen Bauten als auch von modernen Einrichtungen geprägt ist"}, {"kategorie": "", "text": "Eine der bekanntesten Sehenswürdigkeiten in der Nähe ist das [[Hundertwasserhaus]] (Kegelgasse), ein berühmtes, von Friedensreich Hundertwasser entworfenes Wohnhaus, das sich unweit der Löwengasse befindet."}]'::jsonb, ''),
  ('jedlesee', 'Jedlesee', '', '', '', '', 'Jedlesee', '[{"kategorie": "allg.", "text": "historischer Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Ursprünglich war Jedlesee ein eigenständiges Dorf, das 1904 nach Wien eingemeindet wurde"}, {"kategorie": "", "text": "Jedlesee gilt heute als der älteste Teil dieses Bezirks"}, {"kategorie": "", "text": "Der ursprüngliche Name des Ortes war nicht \"Jedlesee\", sondern \"Outcinessevve\" (um 1014), später auch \"Utzinsee\" (um 1120/1125) und \"Utzeinsee\" (1324)"}, {"kategorie": "", "text": "Diese Namen deuten darauf hin, dass der Ort seinen Ursprung in der Nähe eines Gewässers hatte, vermutlich einem Seitenarm der Donau, der \"Schwarzen Lacke\""}, {"kategorie": "", "text": "Die Namen \"Utzinsee\" und \"Utzeinsee\" lassen vermuten, dass der Ort nach einem Mann namens Utzi (möglicherweise eine Koseform von Ulrich) benannt wurde. Dieser könnte der Gründer oder ein bedeutender Bewohner der Siedlung gewesen sein"}, {"kategorie": "", "text": "Über die Jahrhunderte veränderte sich der Name des Ortes mehrfach. Erst ab etwa 1587/1593 findet sich die Bezeichnung \"Jedlesee\""}]'::jsonb, ''),
  ('schwoazlackenau', 'Schwoazlackenau', '', '', '', '', 'Schwarzlackenau', '[{"kategorie": "allg.", "text": "\"Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) am nördlichen Rand Wiens\""}, {"kategorie": "", "text": "Der Name „Schwarzlackenau“ geht auf die ursprüngliche Landschaftsform zurück, die von kleinen Seen, sogenannten [[Lacken]] oder Tümpeln, geprägt war, die nach Regenfällen entstanden und eine dunkle (schwarze) Farbe annahmen"}, {"kategorie": "", "text": "Historisch gesehen war Schwarzlackenau ein landwirtschaftlich geprägtes Gebiet, das sich erst im 19. und 20. Jahrhundert allmählich zu einem Wohngebiet entwickelte. Die Gegend war ursprünglich sumpfig und wenig besiedelt, was durch den Einfluss der Donau und ihre Überflutungen bedingt war. Mit der Verbesserung des Hochwasserschutzes und der [[Donauregulierung]] in Wien begann sich Schwarzlackenau zu entwickeln"}, {"kategorie": "", "text": "In der Nähe von Schwarzlackenau fand am 13. Mai 1809 während der Napoleonischen Kriege ein bedeutendes und blutiges Gefecht statt. Dieses Gefecht war Teil von Napoleons Plan, bei [[Nußdorf]] die Donau zu überschreiten, um die österreichische Armee im Marchfeld zu umzingeln und zu vernichten"}, {"kategorie": "", "text": "Allerdings wurde Napoleons Plan vereitelt, da die österreichischen Truppen die französische Überquerung erfolgreich abwehrten. Das Gefecht trug wesentlich dazu bei, dass die österreichische Armee sich neu formieren konnte, was letztlich zu weiteren entscheidenden Schlachten führte, darunter die berühmte Schlacht bei [[Aspern]] und [[Essling]], in der Napoleon zum ersten Mal eine bedeutende Niederlage erlitt"}, {"kategorie": "", "text": "Im Laufe des 20. Jahrhunderts wurde das Gebiet allmählich urbanisiert, wobei es seine dörfliche Struktur und das ruhige Wohnumfeld weitgehend bewahren konnte. Heute ist es ein beliebtes Wohngebiet, insbesondere für Menschen, die eine naturnahe Umgebung in Kombination mit der Nähe zur Stadt suchen."}]'::jsonb, ''),
  ('grossjedlasduaf', 'Grossjedlasduaf', '', '', '', '', 'Großjedlersdorf', '[{"kategorie": "allg.", "text": "\"Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) im Norden Wiens\""}, {"kategorie": "", "text": "Die Ursprünge von Großjedlersdorf reichen weit in die Vergangenheit zurück, mit der ersten urkundlichen Erwähnung bereits im 12. Jahrhundert. Das Gebiet war lange Zeit ein kleines bäuerliches Dorf mit fruchtbaren Böden, die es zu einem wichtigen landwirtschaftlichen Gebiet machten"}, {"kategorie": "", "text": "1904 wurde Großjedlersdorf zusammen mit anderen umliegenden Ortschaften in Wien eingemeindet und wurde ein Teil des 21. Bezirks, Floridsdorf"}, {"kategorie": "", "text": "Obwohl Großjedlersdorf heute Teil des städtischen Wien ist, hat der Stadtteil viel von seinem ursprünglichen dörflichen Charakter behalten. Neben modernen Wohnbauten gibt es zahlreiche alte Weinhäuser und ländliche Gebäude, die das historische Erbe des Ortes widerspiegeln"}, {"kategorie": "", "text": "Zu den Sehenswürdigkeiten in Großjedlersdorf gehört unter anderem die [[Pfarrkirche]] Großjedlersdorf, die ebenfalls eine lange Geschichte hat. Darüber hinaus sind die [[Heurigenbetriebe]] in der Gegend eine Attraktion für Einheimische und Touristen, die die traditionelle [[Wiener]] Weinkultur erleben möchten."}]'::jsonb, ''),
  ('weinkultua', 'Weinkultua', '', '', '', '', 'Weinkultur', '[{"kategorie": "allg.", "text": "\"lebendige und traditionsreiche Kultur, die tief in der Geschichte und dem Alltag der Stadt Wien verwurzelt ist\""}, {"kategorie": "", "text": "Wien ist die einzige Hauptstadt weltweit, die innerhalb ihrer Stadtgrenzen nennenswerten Weinbau betreibt, was die Wiener Weinkultur einzigartig macht"}, {"kategorie": "", "text": "Diese Kultur umfasst nicht nur den Anbau von Wein, sondern auch die Tradition der Heurigen, die lokale Weinausschankstätten sind, sowie Feste und Rituale, die um den Wein und seine Herstellung kreisen"}, {"kategorie": "", "text": "Der Weinbau in Wien hat eine über 2000 Jahre alte Geschichte, die bis in die Zeit der Römer zurückreicht. Schon damals erkannten die Römer die fruchtbaren Böden und das milde Klima der Region und begannen mit dem Weinbau"}, {"kategorie": "", "text": "Über die Jahrhunderte entwickelte sich der Weinbau zu einem wichtigen Wirtschaftszweig der Stadt. Besonders in den Weinbaugebieten im Norden (wie [[Grinzing]], [[Neustift]] am Walde, [[Sievering]] und [[Nussdorf]] in [[Döbling]] und [[Großjedlersdorf]] und [[Stammersdorf]] in [[Floridsdorf]]) sowie im Süden ([[Mauer]] in [[Liesing]] und [[Oberlaa]] in [[Favoriten]]) wird seit langem Wein kultiviert"}, {"kategorie": "", "text": "Insgesamt gibt es in Wien rund 700 Hektar Weinanbaufläche. Mit ihren malerischen Weingärten, den gemütlichen [[Heurigen]] und den vielfältigen Weinsorten bietet die Wiener Weinkultur eine einzigartige Verbindung zwischen städtischem Leben und ländlicher Tradition und ist ein wesentlicher Bestandteil der Wiener Identität, die sowohl Weinkenner als auch Liebhaber geselliger Zusammenkünfte anzieht"}, {"kategorie": "", "text": "Ein zentraler Bestandteil der Wiener Weinkultur ist die [[Heurigenkultur]]. [[Heurige]] sind traditionelle Weinstuben oder Gasthäuser, in denen der Wein direkt von den Winzern ausgeschenkt wird. Der Name „Heuriger“ kommt vom österreichischen Wort „heurig“, was „diesjährig“ bedeutet und sich auf den frisch produzierten Wein des aktuellen Jahrgangs bezieht. Diese Lokale sind oft gemütlich und bieten eine einfache, aber herzhafte Küche an, die gut mit dem lokalen Wein harmoniert, wie [[Liptauer]], [[Brettljause]] oder [[Schmalzbrot]]"}, {"kategorie": "", "text": "Wien ist besonders bekannt für seinen [[Gemischten]] Satz, eine traditionelle Wiener Spezialität. Dabei handelt es sich um einen Wein, der aus verschiedenen Rebsorten besteht, die gemeinsam in einem Weingarten angebaut und geerntet werden. Dieser Wein vereint die Aromen und Charakteristika der verschiedenen Trauben zu einem unverwechselbaren Geschmack."}]'::jsonb, ''),
  ('schmoizbrod', 'Schmoizbrod', '', '', '', '', 'Schmalzbrot', '[{"kategorie": "allg.", "text": "\"traditioneller, einfacher und herzhafter Imbiss, der vor allem in [[Heurigenlokalen]] serviert wird\" (Determinativkompositum aus \"Schmalz\"=\"Schweinefett\" und \"Brot\"=\"Scheibe Schwarzbrot\")"}, {"kategorie": "", "text": "Das Schmalzbrot steht für traditionelle, ländliche Hausmannskost und wird als einfache, sättigende Mahlzeit geschätzt"}, {"kategorie": "", "text": "Durch die Zugabe von Zwiebeln, Grammeln oder Gewürzen bekommt das Schmalzbrot einen intensiven Geschmack, der gut zu anderen herzhaften Speisen passt"}]'::jsonb, ''),
  ('grammlschmoizbrod', 'Grammlschmoizbrod', '', '', '', '', 'Grammelschmalzbrot', '[{"kategorie": "allg.", "text": "\"traditioneller, einfacher und herzhafter Imbiss, der vor allem in [[Heurigenlokalen]] serviert wird\" (Determinativkompositum aus \"Grammelschmalz\"=\"Schweinefett mit Grieben\" und \"Brot\"=\"Scheibe Schwarzbrot\")"}, {"kategorie": "", "text": "Das Grammelschmalzbrot steht für traditionelle, ländliche Hausmannskost und wird als einfache, sättigende Mahlzeit geschätzt"}, {"kategorie": "", "text": "Es kann mit Zwiebeln, Salz, Pfeffer, oder Paprika noch weiter verfeinert werden"}]'::jsonb, ''),
  ('zwiifaeschmoizbrod', 'Zwiifäschmoizbrod', '', '', '', '', 'Zwiebelschmalzbrot', '[{"kategorie": "allg.", "text": "\"traditioneller, einfacher und herzhafter Imbiss, der vor allem in [[Heurigenlokalen]] serviert wird\" (Determinativkompositum aus \"Zwiebelschmalz\"=\"Schweinefett mit Zwiebeln\" und \"Brot\"=\"Scheibe Schwarzbrot\")"}, {"kategorie": "", "text": "Das Zwiebelschmalzbrot steht für traditionelle, ländliche Hausmannskost und wird als einfache, sättigende Mahlzeit geschätzt"}, {"kategorie": "", "text": "Es kann mit Salz, Pfeffer, oder Paprika noch weiter verfeinert werden"}]'::jsonb, ''),
  ('schdrewasduaf', 'Schdrewasduaf', '', '', '', '', 'Strebersdorf', '[{"kategorie": "allg.", "text": "\"Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) im Norden von Wien am Fuße des [[Bisamberg]]\""}, {"kategorie": "", "text": "Strebersdorf hat eine lange Geschichte, die bis ins Mittelalter zurückreicht. Es wurde erstmals im Jahr 1078 urkundlich erwähnt und war lange Zeit ein kleines bäuerliches Dorf, das vom Weinbau und der Landwirtschaft geprägt war"}, {"kategorie": "", "text": "Der ursprüngliche Name des Ortes lautete \"Strobelinstorf\" - benannt nach den \"Stroblern\", die Strohmatten herstellten oder mit Stroh handelten. Diese Strohmatten spielten damals eine wichtige Rolle, da sie benötigt wurden, um die in [[Nußdorf]] und Wien anlegenden Salzschiffe unbeschädigt an Land zu ziehen"}, {"kategorie": "", "text": "Im Zuge der Stadterweiterung Wiens wurde Strebersdorf im Jahr 1904 zusammen mit anderen Dörfern in den 21. Bezirk ([[Floridsdorf]]) eingegliedert"}, {"kategorie": "", "text": "Der nahegelegene [[Bisamberg]] bietet hervorragende Bedingungen für den Weinbau, und zahlreiche Weingüter und Heurige laden zum Verweilen ein"}, {"kategorie": "", "text": "1912 wurde Strebersdorf an das Netz der elektrischen Straßenbahn und 1913 an die Zweite Hochquellenleitung angeschlossen"}, {"kategorie": "", "text": "Neben der [[Schulbrüderkirche]] und der [[Pfarrkirche]] Strebersdorf sind auch die Pfarr- und Karmelitinnenkirche \"Herz Jesu\" ([[Pfarrkirche Herz-Jesu]]) sowie der [[Strebersdorfer]] Friedhof von Bedeutung."}]'::jsonb, ''),
  ('bruckhaufn', 'Bruckhaufn', '', '', '', '', 'Bruckhaufen', '[{"kategorie": "allg.", "text": "Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) im Norden Wiens"}, {"kategorie": "", "text": "Bruckhaufen grenzt an die [[Donau]] und befindet sich in der Nähe des Naherholungsgebiets [[Donaupark]] und der [[Alten]] Donau"}, {"kategorie": "", "text": "Der Name \"Bruckhaufen\" bedeutet so viel wie „Insel an der Brücke\" und geht damit weit in die Zeit vor der Donauregulierung zurück. Inseln in der unregulierten Donau wurden als Haufen (Häufeln) bezeichnet; der Bruckhaufen war eine Insel zwischen zwei Brücken (siehe [[Zwischenbrücken]])"}, {"kategorie": "", "text": "Ursprünglich war das Gebiet Teil der Donauauen und lag im Überschwemmungsgebiet des Flusses. Durch die [[Donauregulierung]] im 19. Jahrhundert wurde das Gebiet trockengelegt und damit für die Besiedlung nutzbar gemacht. Bruckhaufen entwickelte sich ab dem frühen 20. Jahrhundert zu einem Wohngebiet, das heute überwiegend aus Einfamilienhäusern und kleinen Wohnbauten besteht"}, {"kategorie": "", "text": "Eine der bekanntesten Einrichtungen im Bruckhaufen ist die [[Donaucity-Kirche]] \"Christus, Hoffnung der Welt\", die in den 1990er Jahren errichtet wurde. Sie ist eine moderne, architektonisch herausragende Kirche, die von dem berühmten Architekten Heinz Tesar entworfen wurde und als spirituelles Zentrum für die Anwohner dient."}]'::jsonb, ''),
  ('schuibriada', 'Schuibriada', '', '', '', '', 'Schulbrüder', '[{"kategorie": "allg.", "text": "\"katholische Ordensgemeinschaft, die sich der Erziehung und Bildung von Kindern und Jugendlichen widmet\" (offiziell bekannt als \"die Brüder der Christlichen Schulen\", lateinisch \"Fratres Scholarum Christianarum\" bzw. \"FSC\")"}, {"kategorie": "", "text": "Sie wurden im Jahr 1680 von Jean-Baptiste de La Salle in Frankreich gegründet und zählen heute zu den größten Ordensgemeinschaften der katholischen Kirche, die im Bereich der Bildung tätig ist"}, {"kategorie": "", "text": "1857 kam es zur Gründung der österreichischen Ordensprovinz. Die Schulbrüder ließen sich 1886 in [[Strebersdorf]] nieder, das Provinzialat wurde im 21. Wiener Gemeindebezirk (Floridsdorf) in der Anton-Böck-Gasse 20 eingerichtet ([[Schulbrüderkirche]])"}, {"kategorie": "", "text": "Bauliche Erweiterungen ermöglichten die Aufnahme von Heimschülern und ab 1899 die Führung einer Bürgerschule in der nach dem Schutzpatron der Schulbrüder benannten Anstalt \"Pensionat St. Josef\" (heutige \"De La Salle Schule Strebersdorf\")"}, {"kategorie": "", "text": "Die Schulbrüder sind in vielen Ländern aktiv und betreiben Schulen, Hochschulen und Bildungseinrichtungen auf allen Kontinenten. Sie haben insbesondere in Frankreich, Italien, den USA, Lateinamerika und auch in Österreich und Deutschland eine starke Präsenz."}]'::jsonb, ''),
  ('schuibriadakiachn', 'Schuibriadakiachn', '', '', '', '', 'Schulbrüderkirche', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche in [[Strebersdorf]], einem Teil des 21. Wiener Gemeindebezirks ([[Floridsdorf]]), auch bekannt als \"Kirche Maria Immaculata\""}, {"kategorie": "", "text": "Das ehemalige Strebersdorfer Schloss, welches vom Grafen Maximilian von Grimaus d’Orsay errichtet wurde und 1841 in den Besitz des Stiftes Klosterneuburg gelangte, wurde 1886 dem Orden der [[Schulbrüder]] übergeben. Hier wurde von 1887 bis 1888 die Klosterkirche errichtet, wobei der Turm mit den Glocken allerdings erst 1925 fertiggestellt wurde"}, {"kategorie": "", "text": "Die Kirche gehört zum Provinzialhaus der [[Schulbrüder]] und diente zwischen 1939 und 1961 als Pfarrkirche für die Pfarre [[Strebersdorf]], bevor die [[Maria-Königin-Kirche]] erbaut wurde"}, {"kategorie": "", "text": "Die Schulbrüderkirche wurde 1887/1888 nach den Plänen des Architekten Josef Schmalzhofer als Teil des Klosters der Schulbrüder errichtet. Sie ist ein neugotischer Ziegelrohbau und eine zweischiffige Hallenkirche, die ursprünglich als Klosterkirche konzipiert wurde"}, {"kategorie": "", "text": "Die Kirche ist im neugotischen Stil erbaut, was durch die Verwendung von Ziegeln und die klare, vertikale Ausrichtung der Architektur betont wird. Die Innenausstattung, darunter Gemälde und Figuren, wurden teilweise vom Schulbruder Gabriel Weißenhofer nach Entwürfen von Josef Kastner gestaltet"}, {"kategorie": "", "text": "Besonders erwähnenswert ist die Orgel, die 1941 vom Orgelbau Walcker-Mayer aus Guntramsdorf (einer ehemaligen zweigstelle der Orgelbauanstalt Eberhard Friedrich Walcker aus Ludwigsburg)  geliefert wurde."}]'::jsonb, ''),
  ('jedlasduaf', 'Jedlasduaf', '', '', '', '', 'Jedlersdorf', '[{"kategorie": "allg.", "text": "\"Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) im Norden Wiens\""}, {"kategorie": "", "text": "Die Ursprünge von Jedlersdorf reichen weit in die Vergangenheit zurück, mit der ersten urkundlichen Erwähnung bereits im 12. Jahrhundert. Das Gebiet war lange Zeit ein kleines bäuerliches Dorf mit fruchtbaren Böden, die es zu einem wichtigen landwirtschaftlichen Gebiet machten"}, {"kategorie": "", "text": "1904 wurde Jedlersdorf zusammen mit anderen umliegenden Ortschaften in Wien eingemeindet und wurde ein Teil des 21. Bezirks, Floridsdorf"}, {"kategorie": "", "text": "Obwohl Jedlersdorf heute Teil des städtischen Wien ist, hat der Stadtteil viel von seinem ursprünglichen dörflichen Charakter behalten. Neben modernen Wohnbauten gibt es zahlreiche alte Weinhäuser und ländliche Gebäude, die das historische Erbe des Ortes widerspiegeln"}, {"kategorie": "", "text": "Zu den Sehenswürdigkeiten in Jedlersdorf gehört unter anderem die [[Pfarrkirche]] Großjedlersdorf, die ebenfalls eine lange Geschichte hat. Darüber hinaus sind die [[Heurigenbetriebe]] in der Gegend eine Attraktion für Einheimische und Touristen, die die traditionelle [[Wiener]] Weinkultur erleben möchten."}]'::jsonb, ''),
  ('leopoidau', 'Leopoidau', '', '', '', '', 'Leopoldau', '[{"kategorie": "allg.", "text": "\"Stadtteil im 21. Wiener Gemeindebezirk ([[Floridsdorf]]) im Nordosten von Wien\""}, {"kategorie": "", "text": "Ursprünglich war Leopoldau ein eigenständiges Dorf, das im Jahr 1904 nach Wien eingemeindet wurde. Seit 1734 ist für die Ortschaft die Bezeichnung Leopoldau gebräuchlich, (später \"Alt-Leopoldau\")"}, {"kategorie": "", "text": "Leopoldau liegt im [[Marchfeld]], an der alten Verkehrsroute vom Donauübergang bei [[Jedlesee]] nach Deutsch-Wagram und [[Aspern]]. Lange Zeit war Leopoldau immer wieder durch Hochwässer der Donau gefährdet, deren Seitenarme bis an den Westrand des alten Ortskernes reichten"}, {"kategorie": "", "text": "Die häufigen Überschwemmungen veranlassten die Besitzer ebenerdiger Häuser zur Errichtung sogenannter Wasserzimmer (die sieben bis acht Stufen höher angelegt wurden als die anderen und den Bewohnern Hochwasserschutz boten)"}, {"kategorie": "", "text": "Das Hochwasser von 1830 zerstörte 60 von den damals bestehenden 94 Häusern"}, {"kategorie": "", "text": "Mit der [[Großfeldsiedlung]] entstand in Leopoldau 1966-1973 die zu diesem Zeitpunkt größte Wohnhausanlage Österreichs mit über 21.000 Bewohnern"}, {"kategorie": "", "text": "Besonders bekannt ist Leopoldau für seine [[Pfarrkirche]] St. Michael, die auf das 13. Jahrhundert zurückgeht und eine der ältesten Kirchen im Bezirk Floridsdorf ist"}, {"kategorie": "", "text": "Neben seiner dörflichen Vergangenheit ist Leopoldau auch durch seine industrielle Bedeutung bekannt. Das Gaswerk Leopoldau, das um die Wende zum 20. Jahrhundert errichtet wurde, ist ein markantes Wahrzeichen des Stadtteils und war lange Zeit eines der wichtigsten Gaswerke Wiens."}]'::jsonb, ''),
  ('moachfoeoed', 'Moachfööd', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Marchfeld', '[{"kategorie": "allg.", "text": "\"weitläufige, fruchtbare Ebene im Nordosten von Wien und im östlichen Niederösterreich, die sich zwischen der [[Donau]] im Süden und der March im Osten erstreckt\""}, {"kategorie": "", "text": "Es ist eine der wichtigsten landwirtschaftlichen Regionen Österreichs und bekannt für den Anbau von Gemüse, insbesondere Spargel, Kartoffeln und Getreide"}, {"kategorie": "", "text": "Das Marchfeld erstreckt sich über eine Fläche von etwa 900 km² und bildet eine flache, fruchtbare Landschaft, die sich von den östlichen Wiener Stadtbezirken bis zur slowakischen Grenze erstreckt. Die March, ein Fluss, bildet die natürliche Grenze zwischen Österreich und der Slowakei"}, {"kategorie": "", "text": "Das Marchfeld ist eines der produktivsten Ackerbaugebiete Österreichs und wird häufig als „Kornkammer Wiens“ bezeichnet. Die fruchtbaren Böden und das milde Klima bieten ideale Voraussetzungen für den großflächigen Anbau von Getreide, Obst und Gemüse. Besonders bekannt ist das Marchfeld für den Marchfelder Spargel, der als kulinarische Spezialität gilt"}, {"kategorie": "", "text": "In der Vergangenheit war die Region immer wieder Schauplatz bedeutender historischer Ereignisse. Besonders bekannt ist das Marchfeld als Austragungsort der Schlacht auf dem Marchfeld im Jahr 1278 (auch als [[Schlacht]] bei Dürnkrut und Jedenspeigen bekannt), bei der der böhmische König Ottokar II. Přemysl von den Truppen des römisch-deutschen Königs Rudolf I. von Habsburg besiegt wurde. Diese Schlacht war ein Wendepunkt in der Geschichte des Habsburgerreiches."}]'::jsonb, ''),
  ('shuttleworthschdrossn', 'Shuttleworthschdrossn', '', '', '', '', 'Shuttleworthstraße', '[{"kategorie": "allg.", "text": "Straße im 21. Wiener Gemeindebezirk ([[Floridsdorf]])"}, {"kategorie": "", "text": "Sie befindet sich im Stadtteil Leopoldau in einem Gewerbe- und Industriegebiet und spielt eine bedeutende Rolle für den örtlichen Verkehr, insbesondere durch die Nähe zum [[Industriepark]] Wien Nord und dem [[Gaswerk]] Leopoldau"}, {"kategorie": "", "text": "Die Straße wurde im Jahr 1906 nach der britischen Großindustriellenfamilie Shuttleworth benannt. Besonders im Fokus stehen dabei Joseph Shuttleworth (1819–1883), der Gründer des Unternehmens Clayton & Shuttleworth, sowie sein Bruder John Shuttleworth und sein Sohn Alfred Shuttleworth (1843–1925)"}, {"kategorie": "", "text": "Das Unternehmen Clayton & Shuttleworth, ein britischer Hersteller von Landmaschinen, wurde 1857 in Wien-Landstraße, in der Löwengasse 34, aktiv und betrieb dort eine Fabrik. Die Produktionsstätte wurde 1908 nach Floridsdorf verlegt. Ein markantes Relikt aus dieser Zeit ist der Wasserturm der Fabrik, der noch heute existiert"}, {"kategorie": "", "text": "Die Firma fusionierte 1911 mit der österreichischen Firma Hofherr-Schrantz, einem weiteren wichtigen Unternehmen der Maschinenbauindustrie, und ging schließlich 1970 in den Böhler-Werken auf"}, {"kategorie": "", "text": "Die Shuttleworthstraße ist ein bedeutendes Zeugnis der Industrialisierung in Wien und [[Floridsdorf]]. Nahe der Straße befinden sich auch andere Straßen, die nach bedeutenden Industrieunternehmen benannt sind, wie die [[Hofherr-Schrantz-Gasse]], die [[Trauzlgasse]] und die [[Siemensstraße]]."}]'::jsonb, ''),
  ('trauzlgossn', 'Trauzlgossn', '', '', '', '', 'Trauzlgasse', '[{"kategorie": "allg.", "text": "\"Straße im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), die nach Alois Trauzl (1850–1919) benannt wurde, einem bedeutenden Ingenieur und Unternehmer in der österreichischen Industriegeschichte\""}, {"kategorie": "", "text": "Trauzl war Gründer und Inhaber der Firma Alois Trauzl & Co., die Maschinen und landwirtschaftliche Geräte produzierte"}, {"kategorie": "", "text": "Die Firma Alois Trauzl & Co. war ein wichtiger Bestandteil der Maschinenbauindustrie in Wien. Das Unternehmen stellte Maschinen für den landwirtschaftlichen Einsatz her und trug zur Industrialisierung der Region bei"}, {"kategorie": "", "text": "Die Trauzlgasse befindet sich in einem ehemaligen Industriegebiet von Floridsdorf, das auch von anderen bedeutenden Unternehmen der Maschinenbau- und Landmaschinenindustrie geprägt war. In der Nähe befinden sich auch die [[Hofherr-Schrantz-Gasse]], die [[Shuttleworthstraße]] und die [[Siemensstraße]], die ebenfalls auf die industrielle Geschichte des Bezirks hinweisen."}]'::jsonb, ''),
  ('siimensschdrossn', 'Siimensschdrossn', '', '', '', '', 'Siemensstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße im 21. Wiener Gemeindebezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Sie verläuft durch ein wichtiges Industrie- und Gewerbegebiet und wurde nach dem deutschen Erfinder und Industriellen Werner von Siemens (1816–1892) benannt, der die Firma Siemens & Halske gründete, welche zu einem der weltweit größten Technologiekonzerne wurde"}, {"kategorie": "", "text": "Historisch gesehen war diese Straße Teil der industriellen Entwicklung von Floridsdorf und hat durch die Ansiedlung verschiedener Industrien, darunter die Siemens AG Österreich, maßgeblich zur wirtschaftlichen Bedeutung des Bezirks beigetragen"}, {"kategorie": "", "text": "Die Siemens AG betreibt in diesem Bereich auch heute noch große Produktionsstätten und Büros, was der Straße ihren Namen und ihre Bedeutung verleiht."}]'::jsonb, ''),
  ('schlingamoakd', 'Schlingamoakd', '', '', '', '', 'Schlingermarkt', '[{"kategorie": "allg.", "text": "\"bekannter Markt im 21. Wiener Gemeindebezirk ([[Floridsdorf]])\""}, {"kategorie": "", "text": "Er liegt im Herzen des Bezirks und ist einer der traditionsreichsten Märkte in Wien, auch bekannt als [[Floridsdorfer]] Markt. Der Markt befindet sich an der [[Brünner]] Straße, in der Nähe des [[Floridsdorfer]] Bahnhofs, und ist seit vielen Jahrzehnten ein beliebter Treffpunkt für Anwohner und Besucher aus der Umgebung"}, {"kategorie": "", "text": "Der Schlingermarkt wurde bereits in den 1920er Jahren gegründet und hat sich im Laufe der Zeit zu einem wichtigen Versorgungszentrum im Bezirk entwickelt. Der Name des Marktes geht auf den damaligen Stadtbaumeister Hans Schlinger zurück, der für den Bau und die Planung des Marktes verantwortlich war"}, {"kategorie": "", "text": "Der Markt bietet eine breite Auswahl an frischen Lebensmitteln und internationalen Spezialitäten und ist ein wichtiger Bestandteil des lokalen Lebens in Floridsdorf. Mit seiner Mischung aus Tradition und Moderne bleibt der Schlingermarkt ein einzigartiger und unverwechselbarer Teil Wiens"}]'::jsonb, ''),
  ('hossplotz', 'Hossplotz', '', '', '', '', 'Hoßplatz', '[{"kategorie": "allg.", "text": "Platz im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), der als wichtiger Verkehrsknotenpunkt und öffentlicher Raum dient"}, {"kategorie": "", "text": "Der Platz liegt in unmittelbarer Nähe der [[Brünner]] Straße, einer der Hauptverkehrsachsen des Bezirks, und liegt unweit vom [[Schlingermarkt]] und dem [[Schlingerhof]], zwei bedeutende Einrichtungen in der Umgebung"}, {"kategorie": "", "text": "Der Platz ist nach Franz Hoß (1866–1947) benannt, einem sozial engagierten Gemeinderat von Floridsdorf, der sich vor allem für die Stadtentwicklung und den sozialen Wohnbau in der Region eingesetzt hat. Er war eine einflussreiche Persönlichkeit in der Lokalpolitik (bis 1904 auch Vizebürgermeister) und erwarb sich große Verdienste um die 1904 erfolgte Eingemeindung Floridsdorfs nach Wien.  Er trug maßgeblich zur Gestaltung des Bezirks bei, insbesondere in Hinblick auf Infrastruktur und die Verbesserung der Lebensbedingungen der Arbeiterbevölkerung."}]'::jsonb, ''),
  ('schlingahof', 'Schlingahof', '', '', '', '', 'Schlingerhof', '[{"kategorie": "allg.", "text": "\"bekannte und bedeutende Wohnhausanlage im 21. Wiener Gemeindebezirk ([[Floridsdorf]]), die in den 1920er Jahren im Rahmen des kommunalen Wohnungsbauprogramms des à„Roten Wien“ errichtet wurde\""}, {"kategorie": "", "text": "Er liegt in unmittelbarer Nähe des [[Schlingermarkts]], an der [[Brünner]] Straße, und ist ein markantes Beispiel für den sozialen Wohnbau in der Zwischenkriegszeit in Wien"}, {"kategorie": "", "text": "Der Schlingerhof ist mit seiner repräsentativen Architektur ein herausragendes Beispiel für die monumentalen [[Gemeindebauten]] dieser Zeit. Typisch für die Wohnanlagen des [[Roten]] Wien ist die massige Bauweise, gepaart mit einer reich gegliederten Fassadengestaltung, die durch geometrische Formen, Erker und Loggien aufgelockert wird. Besonders auffällig am Schlingerhof ist der große Torbogen, der die Brünner Straße überspannt und dem Gebäude einen monumentalen Charakter verleiht. Über diesem Torbogen befindet sich eine markante Turmuhr, die zu den charakteristischen Gestaltungselementen zählt"}, {"kategorie": "", "text": "Der Schlingerhof ist, ebenso wie der nahegelegene Schlingermarkt, nach dem damaligen Wiener Stadtbaumeister Hans Schlinger benannt, der für die Planung und den Bau dieser Teile Floridsdorfs verantwortlich war. Er war maßgeblich an der städtebaulichen Entwicklung des Bezirks beteiligt"}, {"kategorie": "", "text": "Heute ist der Schlingerhof ein historisch und architektonisch bedeutsames Wohngebäude in Floridsdorf und ein Symbol für die Errungenschaften des sozialen Wohnbaus in Wien. Er umfasst mehrere Wohnblöcke, die um großzügige Innenhöfe angeordnet sind. Insgesamt bietet er Platz für über 400 Wohnungen."}]'::jsonb, ''),
  ('quadnschdrossn', 'Quadnschdrossn', '', '', '', '', 'Quadenstraße', '[{"kategorie": "allg.", "text": "wichtige Verbindungsstraße im 22. Wiener Gemeindebezirk ([[Donaustadt]]), die die Stadtteile [[Aspern]], [[Hirschstetten]] und [[Breitenlee]] miteinander verbindet"}, {"kategorie": "", "text": "Diese Stadtteile haben sich in den letzten Jahrzehnten stark entwickelt haben, insbesondere durch den Bau von neuen Wohnsiedlungen und die Erschließung von Gewerbegebieten"}, {"kategorie": "", "text": "Entlang der Straße befinden sich mehrere wichtige Einrichtungen, darunter der [[Hirschstettner]] Friedhof (Quadenstraße 11) und die Hirschstettner Blumengärten (Quadenstraße 15)"}, {"kategorie": "", "text": "Zudem gibt es entlang der Straße zahlreiche Kleingartenanlagen, die den ländlichen Charakter der Umgebung unterstreichen."}]'::jsonb, ''),
  ('czartoryskigossn', 'Czartoryskigossn', '', '', '', '', 'Czartoryskigasse', '[{"kategorie": "allg.", "text": "\"ruhige, grüne Wohnstraße, die durch den 17. und 18. Wiener Gemeindebezirk ([[Hernals]] und [[Währing]]) verläuft\""}, {"kategorie": "", "text": "Die Straße führt nördlich vorbei am [[Gersthofer]] Friedhof und ist nach Constantin Adam Fürst Czartoryski benannt ist, einem polnischen Aristokraten und politischen Akteur des 19. Jahrhunderts"}, {"kategorie": "", "text": "Constantin Adam Fürst Czartoryski (* 28. Oktober 1773 in Pulawy, Galizien; † 20. April 1860) entstammte der bedeutenden polnischen Adelsfamilie Czartoryski, die für ihren Einsatz für die polnische Unabhängigkeit und ihre weitreichenden kulturellen und politischen Aktivitäten bekannt war. Czartoryski war eine wichtige Figur im polnischen Adel und spielte eine Rolle im politischen Widerstand gegen die Teilung Polens durch die Nachbarländer Russland, Preußen und Österreich"}, {"kategorie": "", "text": "Die Straße verbindet die historischen Aspekte des Friedhofs mit der modernen Wohnumgebung und spielt eine wichtige Rolle im Verkehrsnetz des Bezirks."}]'::jsonb, ''),
  ('schdockhammerngossn', 'Schdockhammerngossn', '', '', '', '', 'Stockhammerngasse', '[{"kategorie": "allg.", "text": "\"Straße im 14. Wiener Gemeindebezirk ([[Penzing]]) im Stadtteil [[Hütteldorf]]\""}, {"kategorie": "", "text": "Sie wurde nach Hermann Ludwig Graf von Stockhammern (1790–1858) benannt, einem bedeutenden k. k. Kämmerer und Wohltäter, der vor allem durch seine Stiftung eines Armenhauses in Hütteldorf im Jahr 1854 bekannt wurde"}, {"kategorie": "", "text": "Historisch gesehen lag die Stockhammerngasse nahe dem Standort des ursprünglichen [[Hütteldorfer]] Friedhofs (an der Ecke Stockhammerngasse und [[Bergmillergasse]]), der bis zum Bau des neuen Friedhofs genutzt wurde"}, {"kategorie": "", "text": "Heute ist die Stockhammerngasse eine ruhige Wohnstraße in Hütteldorf, die Teil des Verkehrsnetzes von Penzing ist. Sie verbindet Wohnhäuser und Gärten und bietet den Anwohnern Zugang zu wichtigen Einrichtungen in der Umgebung. Die Straße ist zudem ein Erinnerungsort an den Wohltäter Hermann Ludwig Graf von Stockhammern, dessen Stiftung des Armenhauses weiterhin Teil der lokalen Geschichte bleibt."}]'::jsonb, ''),
  ('beagmillagossn', 'Beagmillagossn', '', '', '', '', 'Bergmillergasse', '[{"kategorie": "allg.", "text": "\"Straße im 14. Wiener Gemeindebezirk ([[Penzing]]) im Stadftteil [[Hütteldorf]]\""}, {"kategorie": "", "text": "Sie wurde nach Anton Bergmiller (1821–1870) benannt, einem ehemaligen Brauhausbesitzer und Bürgermeister von Hütteldorf"}, {"kategorie": "", "text": "Anton Bergmiller war im 19. Jahrhundert eine einflussreiche Persönlichkeit in Hütteldorf, einem damals eigenständigen Vorort von Wien. Als Besitzer eines Brauhauses und Bürgermeister setzte er sich aktiv für die wirtschaftliche und infrastrukturelle Weiterentwicklung des Ortes ein. Unter seiner Leitung wurden wichtige Initiativen zur Verbesserung der lokalen Infrastruktur umgesetzt, und er trug maßgeblich zur Entwicklung der Gemeinde bei. Bergmiller starb im Jahr 1870, und seine Verdienste blieben in der Region durch die Benennung der Gasse im Gedächtnis"}, {"kategorie": "", "text": "Historisch gesehen lag der ursprüngliche [[Hütteldorfer]] Friedhof an der Ecke [[Stockhammerngasse]] und Bergmillergasse, bevor er aufgrund von Platzmangel geschlossen und ein neuer Friedhof errichtet wurde"}, {"kategorie": "", "text": "Heute ist die Bergmillergasse eine ruhige Wohnstraße in einem historischen Teil von [[Penzing]] und erinnert an das reiche Erbe und die Entwicklung von [[Hütteldorf]]."}]'::jsonb, ''),
  ('samptwandnagossn', 'Samptwandnagossn', '', '', '', '', 'Samptwandnergasse', '[{"kategorie": "allg.", "text": "Straße im 14. Wiener Gemeindebezirk ([[Penzing]]) im Stadtteil [[Hütteldorf]]"}, {"kategorie": "", "text": "Sie ist nach dem Hütteldorfer Pfarrer Samptwandner benannt, der während der [[Ersten]] Türkenbelagerung Wiens im Jahr 1529 von den Osmanen verschleppt wurde. Die Straße wurde am 10. Juli 1894 vom Wiener Stadtrat offiziell benannt, um an das Schicksal dieses Geistlichen und die historische Bedeutung der Türkenbelagerung zu erinnern"}, {"kategorie": "", "text": "Die Samptwandnergasse verläuft in unmittelbarer Nähe des [[Hütteldorfer]] Friedhofs, der sich an der Samptwandnergasse 6 befindet"}, {"kategorie": "", "text": "Sie ist eine ruhige Wohnstraße im westlichen Teil Wiens, deren Umgebung von Wohnhäusern, Gärten und der friedlichen Atmosphäre des angrenzenden Friedhofsgeprägt ist."}]'::jsonb, ''),
  ('koibegossn', 'Koibegossn', '', '', '', '', 'Kolbegasse', '[{"kategorie": "allg.", "text": "\"Straße im 23. Wiener Gemeindebezirk ([[Liesing]]) im Stadtteil [[Inzersdorf]]\""}, {"kategorie": "", "text": "Die Straße führt am [[Inzersdorfer]] Friedhof vorbei, trug ursprünglich den Namen Friedhofstraße, wurde jedoch später zu Ehren von Josef Kolbe umbenannt, um seine Verdienste für die Region zu würdigen"}, {"kategorie": "", "text": "Josef Kolbe war eine wichtige politische Persönlichkeit in Inzersdorf und Liesing. Als Gemeinderat von [[Inzersdorf]] und später Bezirksrat von [[Liesing]] setzte er sich aktiv für die Entwicklung und Verbesserung der lokalen Infrastruktur und die Anliegen der Bevölkerung ein. Während seiner Amtszeit spielte er eine wesentliche Rolle in der Gestaltung des Bezirks, insbesondere in [[Inzersdorf]], einem ehemals eigenständigen Ort, der später Teil von Wien wurde"}, {"kategorie": "", "text": "Die Straße ist durch ihre Nähe zum [[Inzersdorfer]] Friedhof und ihre Rolle als Wohn- und Verkehrsstraße von besonderer Bedeutung für den Stadtteil [[Inzersdorf]]."}]'::jsonb, ''),
  ('goldemundweg', 'Goldemundweg', '', '', '', '', 'Goldemundweg', '[{"kategorie": "allg.", "text": "\"Straße im 22. Wiener Gemeindebezirk ([[Donaustadt]]) im Stadtteil [[Kagran]]\""}, {"kategorie": "", "text": "Die Straße führt unter anderem zum [[Kagraner]] Friedhof (Adresse: Goldemundweg 134) und ist nach Heinrich Goldemund (1863–1947) benannt, einem bedeutenden österreichischen Stadtplaner und Baudirektor"}, {"kategorie": "", "text": "Goldemund spielte eine zentrale Rolle in der Stadtentwicklung Wiens, insbesondere in den Bereichen Stadtregulierung, Gartenwesen, öffentlicher Wohnungsbau und Verkehrsplanung. Er setzte sich für die Erweiterung städtischer Grünflächen und die Erhaltung des Stadtbilds ein, wobei Projekte wie die Erhaltung des Wald- und Wiesengürtels und die [[Wiener]] Höhenstraße auf ihn zurückgehen"}, {"kategorie": "", "text": "Der Goldemundweg liegt in einem ruhigen Wohngebiet und dient vor allem als Verkehrsverbindung zum [[Kagraner]] Friedhof, einem wichtigen Begräbnisort im Bezirk Donaustadt."}]'::jsonb, ''),
  ('thuernlhofschdrossn', 'Thürnlhofschdrossn', '', '', '', '', 'Thürnlhofstraße', '[{"kategorie": "allg.", "text": "\"Straße im 11. Wiener Gemeindebezirk ([[Simmering]]), im Stadtteil [[Kaiserebersdorf]]\""}, {"kategorie": "", "text": "Sie ist eine zentrale Verbindungsstraße in der Gegend und führt unter anderem zum [[Kaiserebersdorfer]] Friedhof (Adresse: Thürnlhofstraße 27)"}, {"kategorie": "", "text": "Der Name der Straße geht auf den Thürnlhof zurück, einen ehemaligen Gutshof in der Umgebung von Kaiserebersdorf"}, {"kategorie": "", "text": "Der Thürnlhof erhielt seinen Namen von zwei „Thürndln“ (Türmen oder kleinen Festungswerken), die ursprünglich auf dem Gelände standen. Diese waren Teil von verfallenen Bauwerken, die Michael Pfeiffer, der Unterkoch von König Ferdinand I., zu einem schmucken Herrenhaus umgestaltete. Der Hof spielte in der Geschichte Kaiserebersdorfs eine wichtige Rolle und beherbergte bedeutende Persönlichkeiten"}, {"kategorie": "", "text": "Während der Napoleonischen Kriege verbrachte Napoleon Bonaparte eine Nacht im Thürnlhof, kurz vor der [[Schlacht]] bei Aspern im Jahr 1809. Der Hof wurde 1832 in eine Zuckerfabrik umgewandelt und ging 1876 in den Besitz der [[Gemeinde]] Wien über, die dort eine Volksschule einrichtete"}, {"kategorie": "", "text": "Heute ist der Thürnlhof ein gewöhnliches Miethaus, doch der Altbau des 16. Jahrhunderts ist noch im Mittelbereich erkennbar"}, {"kategorie": "", "text": "Die Thürnlhofstraße wurde nach diesem bedeutenden historischen Anwesen benannt und erinnert an die lange Geschichte und den Einfluss des Thürnlhofs auf die Region."}]'::jsonb, ''),
  ('muennichplotz', 'Münnichplotz', '', '', '', '', 'Münnichplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 11. Wiener Gemeindebezirk ([[Simmering]])  im Stadtteil [[Kaiserebersdorf]]\""}, {"kategorie": "", "text": "Der Platz wurde am 5. Juli 1894 vom Wiener Stadtrat nach dem Weltpriester und langjährigen Kaiserebersdorfer Pfarrer Philipp Jakob Münnich (1785–1856) benannt, der von 1830 bis 1856 in Kaiserebersdorf tätig war. Münnich ist vor allem dafür bekannt, dass er sich während der Revolution von 1848 persönlich dafür einsetzte, die Bevölkerung von Kaiserebersdorf vor Plünderungen und Gewalttätigkeiten durch die eigene Soldatenmacht, die Soldateska, zu schützen"}, {"kategorie": "", "text": "Der Münnichplatz beherbergt auch den Thürnlhof (siehe [[Thürnlhofstraße]]) und die historische [[Pfarrkirche]] Kaiserebersdorf, die den Heiligen Peter und Paul geweiht ist, und liegt gegenüber des [[Schlosses]] Kaiserebersdorf (einem historischen Bauwerk und bedeutendem Wahrzeichen des Stadtteils, das tief in der Geschichte Kaiserebersdorfs verwurzelt ist)"}, {"kategorie": "", "text": "Zusammen mit dem Thürnlhof, der Kirche und dem Schloss bildet der Münnichplatz das historische Zentrum von [[Kaiserebersdorf]]."}]'::jsonb, ''),
  ('wueazbuaggossn', 'Wüazbuaggossn', '', '', '', '', 'Würzburggasse', '[{"kategorie": "allg.", "text": "bedeutsame Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), an welcher der Hauptsitz des Österreichischen Rundfunks (ORF)  am [[Küniglberg]] sowie auch der Lainzer Friedhof liegt, welcher 1876 eröffnet wurde"}, {"kategorie": "", "text": "Die Würzburggasse verläuft durch den westlichen Teil Hietzings ([[Lainz]] und [[Speising]]) und ist nach der Schlacht bei Würzburg benannt, einem bedeutenden Sieg der österreichischen Truppen über die französische Armee am 3. September 1796 während der Koalitionskriege"}, {"kategorie": "", "text": "Würzburg ist die Hauptstadt Unterfrankens in Bayern, und der Sieg der Österreicher war ein wichtiger Moment in der militärischen Geschichte Österreichs"}, {"kategorie": "", "text": "Die Würzburggasse verläuft durch eine der gehobenen, grünen und ruhigen Gegenden Wiens, die für ihre Villen und großbürgerlichen Wohnhäuser bekannt ist."}]'::jsonb, ''),
  ('roabochaschdrossn', 'Roabochaschdrossn', '', '', '', '', 'Rohrbacherstraße', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 13. Wiener Gemeindebezirk ([[Hietzing]], im Stadtteil [[Ober-St]].-Veit), die nach dem bedeutenden Wagenfabrikanten Josef Rohrbacher benannt ist\""}, {"kategorie": "", "text": "Josef Rohrbacher wurde am 25. Februar 1817 in Hammern, Böhmen (heute Hamry, Tschechische Republik) geboren und starb am 23. Dezember 1883 in Ober-St.-Veit. Er war ein erfolgreicher Unternehmer und Gründer einer Wagnerwerkstätte, die sich ab 1853 zu einer der größten Wagenfabriken Wiens entwickelte. Rohrbacher spezialisierte sich zunächst auf den Bau von Postwagen und konstruierte schließlich eine eigene Pferdeomnibustype, einen zehnsitzigen Wagen mit zwei Coupés, der in Wien weit verbreitet war"}, {"kategorie": "", "text": "In den 1860er Jahren erhielt seine Fabrik zunehmend Aufträge vom Kriegsministerium, darunter die Herstellung von Train- und Sanitätsfahrzeugen sowie Festungsfeldbahnen. Dadurch erlangte Rohrbachers Unternehmen besondere Bedeutung für den militärischen Transportsektor"}, {"kategorie": "", "text": "Die Rohrbacherstraße liegt in einem gutbürgerlichen und grünen Teil von Hietzing, der für seine Villen, gepflegten Gärten und historischen Gebäude bekannt ist. Aufgrund der Lage und des Charakters von Ober-St.-Veit gehört die Rohrbacherstraße zu einem der eher ruhigeren, weniger verkehrsbelasteten Bereiche des Bezirks."}]'::jsonb, ''),
  ('schdreckaplotz', 'Schdreckaplotz', '', '', '', '', 'Streckerplatz', '[{"kategorie": "allg.", "text": "\"zentraler und bedeutender Platz im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Stadtteil [[Ober-Sankt-Veit]]\""}, {"kategorie": "", "text": "Der Platz ist nach Alexander Strecker (1816–1908) benannt - einer historischen Persönlichkeit, die sowohl im Bereich des Eisenbahnwesens als auch als Bürgermeister von Ober-Sankt-Veit eine wichtige Rolle spielte"}, {"kategorie": "", "text": "Alexander Strecker wurde am 18. Juni 1816 in Rüsselsheim am Main geboren und starb am 18. Jänner 1908 in Mannheim. Als Zivilingenieur und Betriebsingenieur arbeitete er bei verschiedenen Eisenbahngesellschaften, darunter der Wien-Gloggnitzer Bahn, der Gmunden-Budweiser Bahn und der Kaiserin-Elisabeth-Westbahn. In dieser Funktion entwickelte er mehrere Projekte und Betriebsideen, die zum Aufbau des österreichischen Eisenbahnwesens beitrugen, auch wenn über die Details seiner Arbeiten wenig bekannt ist"}, {"kategorie": "", "text": "Von 1861 bis 1873 vertrat Strecker die Kruppstahlwerke in Österreich. In Ober-St.-Veit war er nicht nur als Bürgermeister tätig (1877–1879), sondern auch Mitbegründer der katholischen Kinderbewahranstalt à„Elisabethinum“, obwohl er selbst evangelischer Konfession war. Diese Institution existiert bis heute und befindet sich in der [[Vitusgasse]] 2 im 13. Bezirk. Im Jahr 1885 übersiedelte Strecker nach Mannheim, wo er bis zu seinem Tod lebte und auf dem Hauptfriedhof begraben wurde"}, {"kategorie": "", "text": "Der Platz liegt in einer überwiegend ruhigen Wohngegend in Ober-Sankt-Veit - einem Stadtteil, der für seine grünen, gehobenen Wohngebiete mit Villen, Gärten und historischer Bausubstanz bekannt ist."}]'::jsonb, ''),
  ('schdreckapark', 'Schdreckapark', '', '', '', '', 'Streckerpark', '[{"kategorie": "allg.", "text": "\"ruhige Grünanlage im Herzen von [[Ober-St]].-Veit im 13. Wiener Gemeindebezirk ([[Hietzing]]) zwischen der [[Rohrbacherstraße]], dem [[Streckerplatz]] und der [[Auhofstraße]]\""}, {"kategorie": "", "text": "Der Streckerpark entstand auf dem Gelände des ehemaligen Friedhofs von Ober-St.-Veit, der sich ursprünglich um die Pfarrkirche Ober-St.-Veit befand. Nachdem der Friedhof zu klein geworden war und ein neuer Friedhof in der Gemeindeberggasse (siehe [[Ober-Sankt-Veiter]] Friedhof)   eröffnet wurde, wurde das Gelände des alten Friedhofs umgestaltet und in eine Parkanlage umgewandelt"}, {"kategorie": "", "text": "Der Platz ist nach Alexander Strecker (1816–1908) benannt - einer historischen Persönlichkeit, die sowohl im Bereich des Eisenbahnwesens als auch als Bürgermeister von Ober-Sankt-Veit eine wichtige Rolle spielte"}, {"kategorie": "", "text": "Alexander Strecker wurde am 18. Juni 1816 in Rüsselsheim am Main geboren und starb am 18. Jänner 1908 in Mannheim. Als Zivilingenieur und Betriebsingenieur arbeitete er bei verschiedenen Eisenbahngesellschaften, darunter der Wien-Gloggnitzer Bahn, der Gmunden-Budweiser Bahn und der Kaiserin-Elisabeth-Westbahn. In dieser Funktion entwickelte er mehrere Projekte und Betriebsideen, die zum Aufbau des österreichischen Eisenbahnwesens beitrugen, auch wenn über die Details seiner Arbeiten wenig bekannt ist"}, {"kategorie": "", "text": "Von 1861 bis 1873 vertrat Strecker die Kruppstahlwerke in Österreich. In Ober-St.-Veit war er nicht nur als Bürgermeister tätig (1877–1879), sondern auch Mitbegründer der katholischen Kinderbewahranstalt à„Elisabethinum“, obwohl er selbst evangelischer Konfession war. Diese Institution existiert bis heute und befindet sich in der [[Vitusgasse]] 2 im 13. Bezirk. Im Jahr 1885 übersiedelte Strecker nach Mannheim, wo er bis zu seinem Tod lebte und auf dem Hauptfriedhof begraben wurde"}, {"kategorie": "", "text": "Der Streckerpark ist ein kleiner, aber idyllischer Stadtpark, der von den Anwohnern gerne als Erholungsraum genutzt wird. Er bietet eine ruhige und grüne Umgebung, die zum Spazierengehen, Entspannen und Verweilen einlädt."}]'::jsonb, ''),
  ('jaunaschdrossn', 'Jaunaschdrossn', '', '', '', '', 'Jaunerstraße', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]), die nach Franz Ritter von Jauner (1831–1900) benannt ist, einem bedeutenden österreichischen Theaterdirektor und Schauspieler\""}, {"kategorie": "", "text": "Franz Jauner war ein vielseitig begabter Künstler, der zunächst in der Musiktheorie ausgebildet wurde, jedoch eine große Leidenschaft für das Theater entwickelte. Nach seinem Debüt im [[Pasqualatitheater]] im Jahr 1848 führte ihn seine Karriere an verschiedene renommierte Bühnen, darunter das [[Burgtheater]], das [[Carltheater]] und die [[Hofoper]]"}, {"kategorie": "", "text": "Besonders während seiner Zeit als Direktor der Hofoper (ab 1875) prägte er die Wiener Theaterszene entscheidend. Zu seinen künstlerischen Höhepunkten zählen die Erstaufführung von Richard Wagners \"Ring des Nibelungen\" sowie die Einführung der Opernsoiree und Opernredoute an der Hofoper"}, {"kategorie": "", "text": "Jauner war auch an den Erstaufführungen von Verdis \"Requiem\" und Bizets \"Carmen\" beteiligt, die unter seiner Leitung in Wien stattfanden. Trotz seiner künstlerischen Erfolge kämpfte er mit finanziellen Schwierigkeiten, was ihn schließlich zu einem tragischen Lebensende führte (Selbstmord im Jahr 1900)"}, {"kategorie": "", "text": "Die Jaunerstraße liegt in einem gehobenen Wohngebiet, das durch historische Villen, Grünflächen und eine entspannte, ländlich anmutende Atmosphäre geprägt ist."}]'::jsonb, ''),
  ('elisabetinum', 'Elisabetinum', '', '', '', '', 'Elisabethinum', '[{"kategorie": "allg.", "text": "\"Bildungs- und Betreuungseinrichtung in der [[Vitusgasse]] 5 im 13. Wiener Gemeindebezirk ([[Hietzing]]), im Stadtteil [[Ober-Sankt-Veit]]\""}, {"kategorie": "", "text": "Das Elisabethinum wurde von Alexander Strecker, dem ehemaligen Bürgermeister von Ober-St.-Veit, mitbegründet und nach der Kaiserin Elisabeth benannt. Die Einrichtung besteht seit dem späten 19. Jahrhundert und diente ursprünglich als katholische Kinderbewahranstalt"}, {"kategorie": "", "text": "Alexander Strecker, obwohl selbst evangelischen Glaubens, setzte sich maßgeblich für die Errichtung dieser katholischen Einrichtung ein. Sie diente der Betreuung von Kindern, ähnlich einer frühen Form von Kindergarten oder Kinderhort"}, {"kategorie": "", "text": "Im Laufe der Zeit wurde das Elisabethinum weiter ausgebaut und modernisiert, um den sich verändernden Anforderungen gerecht zu werden. Heute ist es eine Bildungsstätte und eine Betreuungseinrichtung, die sich insbesondere um Kinder kümmert, mit einem Schwerpunkt auf Bildung, Betreuung und Erziehung."}]'::jsonb, ''),
  ('vitusgossn', 'Vitusgossn', '', '', '', '', 'Vitusgasse', '[{"kategorie": "allg.", "text": "\"bedeutende und historische Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), im Stadtteil [[Ober-Sankt-Veit]]\""}, {"kategorie": "", "text": "Die Straße wurde am 10. Juli 1894 vom Wiener Stadtrat nach dem Heiligen Vitus benannt"}, {"kategorie": "", "text": "Der Heilige Vitus ist ein christlicher Märtyrer und einer der 14 Nothelfer in der katholischen Kirche. Er lebte vermutlich im 3. oder 4. Jahrhundert und ist der Schutzpatron der Schauspieler, Tänzer und Epileptiker. In Österreich, insbesondere in Ober-Sankt-Veit, wird ihm besondere Verehrung zuteil, da die örtliche Pfarrkirche ([[Ober-Sankt-Veiter-Kirche]]) dem Heiligen Vitus geweiht ist, was den Namensbezug der Gasse unterstreicht"}, {"kategorie": "", "text": "Die Vitusgasse liegt in einem ruhigen und gehobenen Wohngebiet von Ober-Sankt-Veit und ist von historischen Gebäuden, Villen und gepflegten Grünanlagen umgeben. In der Vitusgasse 5 befindet sich das [[Elisabethinum]], eine traditionsreiche Bildungs- und Betreuungseinrichtung. Die Gasse ist ein integraler Bestandteil des historischen Stadtkerns von Ober-Sankt-Veit."}]'::jsonb, ''),
  ('woifroodplotz', 'Woifroodplotz', '', '', '', '', 'Wolfrathplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz 13. Wiener Gemeindebezirk ([[Hietzing]]), im Stadtteil [[Ober-Sankt-Veit]]\""}, {"kategorie": "", "text": "Er wurde am 10. Juli 1894 vom Stadtrat nach Anton Wolfrath (1582–1639), einem bedeutenden Fürstbischof von Wien und Diplomaten, benannt. Vor der Umbenennung hieß der Platz Kirchenplatz, da auf ihm auch die [[Pfarrkirche]] Ober-Sankt-Veit liegt"}, {"kategorie": "", "text": "Anton Wolfrath, der Namensgeber des Platzes, war ein bedeutender Kirchenmann und Staatsmann. Geboren 1582 in Köln, wurde er 1630 zum Bischof von Wien ernannt und war zudem kaiserlicher Rat und Präsident der Hofkammer. Er spielte eine wichtige Rolle in der Gegenreformation und förderte den Bau von Kirchen und Klöstern, darunter die [[Universitätskirche]] und die Kaisergruft der Kapuziner ([[Kapuzinergruft]]). Wolfrath war maßgeblich an der Rekatholisierung von Österreich beteiligt und unterstützte katholische Orden wie die Jesuiten und Serviten"}, {"kategorie": "", "text": "Der Wolfrathplatz war seit September 1887 ein wichtiger Verkehrsknotenpunkt, da er die Endstation einer Linie der Dampftramway beherbergte. Später diente er als Endstation verschiedener Straßenbahnlinien, darunter die Linie 58 (1908 bis 1914) und die Linie 158 (1914 bis 1958). Die Straßenbahn wendete hier ohne Schleife, sondern mit einer Rangierweiche, was den historischen Verkehrsbetrieb prägte"}, {"kategorie": "", "text": "Der Wolfrathplatz liegt im historischen Zentrum von [[Ober-Sankt-Veit]] und schließt an zwei wichtige Verkehrsadern an: die [[Hietzinger]] Hauptstraße im Südosten und die [[Vitusgasse]] im Süden. Der Platz ist von historischen Gebäuden, Wohnhäusern und kleinen Geschäften umgeben, was ihm eine ruhige, aber zentrale Funktion im Stadtteil verleiht"}]'::jsonb, ''),
  ('univeasitaetskiachn', 'Univeasitätskiachn', '', '', '', '', 'Universitätskirche', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 1. Wiener Gemeindebezirk ([[Innere]] Stradt) am [[Dr]].-Ignaz-Seipel-Platz (auch Neue Jesuitenkirche genannt)\""}, {"kategorie": "", "text": "Sie ist den Heiligen Ignatius von Loyola und Franz Xaver geweiht, gehört zu den bedeutendsten barocken Kirchen Wiens und wird von den Jesuiten betrieben"}, {"kategorie": "", "text": "Die Kirche hat ihre Ursprünge in der Mitte des 16. Jahrhunderts, als König Ferdinand I. den Jesuiten das ehemalige Karmelitenkloster \"Am Hof\" übergab. Später verlegten die Jesuiten ihren Standort in die Nähe der alten Universität. Dort errichteten sie von 1623 bis 1627 eine neue Kirche, die zu Ehren Mariens und der Heiligen Ignatius und Franz Xaver geweiht wurde"}, {"kategorie": "", "text": "Die heutige Gestalt der Kirche stammt von Andrea Pozzo, der sie von 1703 bis 1707 umgestaltete. Pozzo fügte die barocke Fassade und die Türme hinzu und schuf bedeutende Fresken und Altarbilder"}, {"kategorie": "", "text": "Die Kirche wurde 1773 nach der Aufhebung des Jesuitenordens vom Staat übernommen, war kurzzeitig Garnisonskirche und wurde ab 1783 eine Stadtpfarrkirche. Seit 1857 ist sie wieder im Besitz der Jesuiten und dient auch als Universitätskirche."}]'::jsonb, ''),
  ('konzueuesgedaechniskiachn', 'Konzüüsgedächniskiachn', '', '', '', '', 'Konzilsgedächtniskirche', '[{"kategorie": "allg.", "text": "\"römisch-katholische Kirche im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Stadtteil [[Lainz]] am [[Kardinal-König-Platz]] 3\" (auch bekannt als Konzilsgedächtniskirche „Zur Allerheiligsten Dreifaltigkeit\", ehemals Ordenskirche „Zum Heiligen Herzen Jesu\")"}, {"kategorie": "", "text": "Sie wurde zwischen 1967 und 1968 nach den Plänen des Architekten Josef Lackner im Auftrag der Erzdiözese Wien errichtet und am 22. Juni 1968 geweiht"}, {"kategorie": "", "text": "Die Kirche ersetzte eine frühere Kapelle, die im kaiserlichen Jagdschloss stand, das später von den Jesuiten als Exerzitienhaus genutzt wurde. 1885/1886 wurde eine neoromanische Kapelle an das Exerzitienhaus angebaut"}, {"kategorie": "", "text": "Die Konzilsgedächtniskirche ist eine moderne Kirche, die im Gedenken an das Zweite Vatikanische Konzil (1962–1965) errichtet wurde, und folgt den liturgischen Reformen, die dort beschlossen wurden. Ihr schlichtes Design verzichtet auf Türme, was dem Bau eine vergleichsweise geringe Höhe verleiht. Die Kirche wurde 2012 zum 50-jährigen Jubiläum des Zweiten Vaticanums renoviert"}, {"kategorie": "", "text": "In unmittelbarer Nähe befindet sich das Kardinal-König-Haus, ein Bildungszentrum der Jesuiten und der Caritas, das eng mit der Kirche verbunden ist. Die Konzilsgedächtniskirche dient sowohl als Pfarrkirche als auch als Ordenskirche und ist ein wichtiger Ort für religiöse Bildung und Exerzitien."}]'::jsonb, ''),
  ('jogdschlossgossn', 'Jogdschlossgossn', '', '', '', '', 'Jagdschlossgasse', '[{"kategorie": "allg.", "text": "\"zentrale Wohn- und Verkehrsstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Stadtteil [[Lainz]]\""}, {"kategorie": "", "text": "Sie wurde am 10. Juli 1894 nach einem ehemaligen kaiserlichen Jagdschloss in Lainz benannt. Dieses Jagdschloss, das um 1830 nachweisbar ist, wurde 1884 vom Jesuitenorden erworben und in ein Exerzitienhaus umgebaut"}, {"kategorie": "", "text": "Anstelle der ursprünglichen Schlosskapelle wurde 1885/1886 die neuromanische Kirche „Zum Heiligsten Herzen Jesu“ errichtet, die später, 1950, erweitert wurde. In den Jahren 1967/1968 wurde nach Plänen von Josef Lackner die [[Konzilsgedächtniskirche]] zu Ehren des Heiligen Ignatius von Loyola gebaut. Diese turmlose Kirche, die den modernen liturgischen Anforderungen entspricht, ist Teil des heutigen Jesuiten-Exerzitien- und Bildungshauses Lainz sowie des Pfarramts Lainz"}, {"kategorie": "", "text": "Die Jagdschlossgasse verbindet somit historisch das ehemalige kaiserliche Jagdschloss mit der heutigen kirchlichen Nutzung und ist ein wichtiger Bezugspunkt zur Geschichte des Stadtteils [[Lainz]]."}]'::jsonb, ''),
  ('napoleonwoid', 'Napoleonwoid', '', '', '', '', 'Napoleonwald', '[{"kategorie": "allg.", "text": "\"kleines Waldgebiet im 13. Wiener Gemeindebezirk ([[Hietzing]]), in der Nähe des [[Lainzer]] Tiergartens und des Stadtteils [[Ober-St]].-Veit\""}, {"kategorie": "", "text": "Die Namensgebung des Napoleonwalds erinnert an die Besetzung Wiens durch Napoleons Truppen während der [[Napoleonischen]] Kriege. In dieser Zeit nutzten die französischen Truppen das Gebiet als Lagerplatz. Obwohl es keine konkreten historischen Bauten oder Denkmäler gibt, die direkt an Napoleons Aufenthalt erinnern, trägt der Wald seinen Namen als Teil der historischen Erinnerung"}, {"kategorie": "", "text": "Der Napoleonwald ist heute ein beschauliches, naturbelassenes Waldstück, das von gutbürgerlichen Wohngebieten umgeben ist. Er dient als Naherholungsgebiet und bietet eine grüne Oase in einem der ruhigeren und gehobenen Teile Wiens."}]'::jsonb, ''),
  ('biaheislbeag', 'Biaheislbeag', '', '', '', '', 'Bierhäuselberg', '[{"kategorie": "allg.", "text": "\"271 Meter hoher Hügel im 14. Wiener Gemeindebezirk ([[Penzing]]), im Stadtteil [[Hütteldorf]]\""}, {"kategorie": "", "text": "Der Bierhäuselberg hat seinen Namen von den ausgedehnten Bierkellern der ehemaligen Hütteldorfer Brauerei. Diese befanden sich am Fuß des Hügels und waren Teil einer der bedeutendsten Brauereien im Umland Wiens im 19. Jahrhundert"}, {"kategorie": "", "text": "Die Hütteldorfer Brauerei, deren Ursprünge bis ins 16. Jahrhundert zurückreichen, entwickelte sich im Laufe der Zeit zu einem wichtigen wirtschaftlichen Zentrum der Region. Sie war nicht nur für ihre Bierproduktion bekannt, sondern auch für ihre großen Bierkeller, die sich entlang der Linzer Straße erstreckten und in den Hügel hineinreichten. Dort befand sich auch das namensgebende \"Bierhäusl\", ein Teil der Brauereianlage"}, {"kategorie": "", "text": "Im 19. Jahrhundert erlebte die Brauerei unter den Besitzern Anton Bergmiller und anderen einen Aufschwung und avancierte zu einer der größten Brauereien Wiens und gleichzeitig auch zum Ausflugsziel für die Wiener Bevölkerung. Der Bierhäuselberg und das Brauhaus waren beliebte Treffpunkte, an denen auch Konzerte und gesellschaftliche Veranstaltungen stattfanden"}, {"kategorie": "", "text": "Nach der Schließung der Brauerei in den 1930er Jahren wurde das Gelände um den Bierhäuselberg für Wohnzwecke erschlossen. Heute ist der Bierhäuselberg ein ruhiges Wohngebiet mit Gartensiedlungen, das immer noch an seine Vergangenheit als Standort der Hütteldorfer Brauerei erinnert."}]'::jsonb, ''),
  ('woifasbeag', 'Woifasbeag', '', '', '', '', 'Wolfersberg', '[{"kategorie": "allg.", "text": "\"Hügel mit einer Seehöhe von 322 Metern im 14. Wiener Gemeindebezirk ([[Penzing]])\""}, {"kategorie": "", "text": "Der Hügel war ursprünglich eine dicht bewaldete Kuppe zwischen dem Wien- und dem Haltertal, gelegen zwischen [[Hütteldorf]] und [[Weidlingau]]"}, {"kategorie": "", "text": "Nach dem Ersten Weltkrieg wurde der Wald infolge der Brennstoffnot abgeholzt, und das Gebiet wurde später durch Siedlungen bebaut"}, {"kategorie": "", "text": "Auf dem höchsten Punkt des Wolfersbergs befindet sich ein Wasserturm, der 1961 errichtet wurde. Dieser 12,7 Meter hohe Wasserturm Wolfersberg dient nicht nur der Wasserversorgung (mit einem Behältervolumen von 63,2 Kubikmetern), sondern auch als Funk- und Sendeturm. Er verbreitet das Radioprogramm von Radio 88,6 auf 90,5 MHz und das Signal des NDB-Funkfeuers STE, welches als Navigationshilfe für Flugzeuge dient, die in Schwechat landen"}, {"kategorie": "", "text": "Der Turm trägt seit 1981 eine 18,8 Meter hohe Sendeantenne, wodurch seine Gesamthöhe 31,5 Meter beträgt. Der Wasserturm auf dem Wolfersberg ist weltweit einzigartig, da er als einziger Wasserturm über eine Sendeantenne für einen Langwellensender verfügt."}]'::jsonb, ''),
  ('pasqualatiteata', 'Pasqualatiteata', '', '', '', '', 'Pasqualatitheater', '[{"kategorie": "allg.", "text": "\"kleines Theater in Wien, das im 19. Jahrhundert von der Familie Pasqualati betrieben wurde\""}, {"kategorie": "", "text": "Es befand sich im [[Schönbornpalais]] in der [[Laudongasse]] 15-19 im 8. Wiener Gemeindebezirk ([[Josefstadt]]) und wurde 1841 von Johann Baptist Freiherr von Pasqualati für seine Gattin Amalie Pasqualati, eine frühere Schauspielerin des [[Josefstädter]] Theaters, eröffnet"}, {"kategorie": "", "text": "Ursprünglich war das Theater ein Liebhabertheater, das vor allem Lustspiele und Possen für einen kleinen privaten Kreis aufführte. Gelegentlich wurden auch Opern und ab 1860 Operetten, wie etwa Werke von Jacques Offenbach, ins Programm aufgenommen. Zu den meistgespielten Autoren gehörte August von Kotzebue, und viele zukünftige Theatergrößen, wie Fichtner und Jauner, debütierten auf dieser Bühne"}, {"kategorie": "", "text": "Amalie Pasqualati betrieb zudem eine Theaterschule, die großen Zulauf fand. 1860 suchte sie um eine Bewilligung zur Errichtung eines öffentlichen Theaters an, die ihr schließlich erteilt wurde. Dennoch musste das Theater aus finanziellen Gründen am 16. Februar 1862, nach einer Wohltätigkeitsveranstaltung für die Opfer der Donauüberschwemmung, schließen"}, {"kategorie": "", "text": "Später wurde in den Räumlichkeiten eine Schauspielschule von Julius Conradi eröffnet, und Amalie Pasqualati führte ab 1866 das [[Harmonietheater]]."}]'::jsonb, ''),
  ('harmoniiteata', 'Harmoniiteata', '', '', '', '', 'Harmonietheater', '[{"kategorie": "allg.", "text": "\"historisches Wiener Theater in der Alservorstadt (Wasagasse 9, 1090 Wien, [[Alsergrund]])\""}, {"kategorie": "", "text": "Es wurde nach Plänen der Baumeister Dräsche und Weiß erbaut und am 20. Jänner 1866 eröffnet\""}, {"kategorie": "", "text": "Die Gründerin des Theaters, Amalia von Pasqualati, war eine ehemalige Schauspielerin des [[Josefstädter]] Theaters, die bereits zuvor ein Liebhabertheater im [[Schönbornpalais]] betrieben hatte"}, {"kategorie": "", "text": "Das Harmonietheater präsentierte ein buntes Programm aus Operetten, Lustspielen und Possen. Zu den bekanntesten Komponisten und Autoren, deren Werke aufgeführt wurden, zählten Ludwig Anzengruber, Carl Millöcker und Johann Nestroy"}, {"kategorie": "", "text": "Das Theater erlebte jedoch eine wechselvolle Geschichte mit mehreren Direktoren und finanziellen Schwierigkeiten. 1867 wurde es vorübergehend geschlossen, dann wiedereröffnet, aber blieb weiter unprofitabel"}, {"kategorie": "", "text": "1868 wurde es schließlich in Orpheum umbenannt und auf Varieté und Artistik spezialisiert, was jedoch ebenfalls nur kurzzeitig Erfolg brachte"}, {"kategorie": "", "text": "Trotz späterer Übernahmen und Umbenennungen schloss das Theater endgültig im Jahr 1928."}]'::jsonb, ''),
  ('orpheum', 'Orpheum', '', '', '', '', 'Orpheum', '[{"kategorie": "", "text": "Es wurde 1957 ursprünglich als Kino unter dem Namen „Zentrum 22“ eröffnet und bot Platz für über 500 Besucher. Wie viele andere Wiener Kinos musste es 1976 schließen und diente zeitweise als Jugendzentrum"}, {"kategorie": "", "text": "In den frühen 1980er Jahren übernahm der Kulturverein Donaustadt die Bühne, nannte sie „Orpheum“ und bespielte sie mit einem breiten Angebot an kulturellen Veranstaltungen wie Theater, Konzerten und Lesungen"}, {"kategorie": "", "text": "In den 1990er Jahren stand das Orpheum kurz vor der endgültigen Schließung, da ein Supermarkt an seiner Stelle geplant war. Dank des Einsatzes des Kulturvereins und einer neuen Betreibergruppe konnte das Orpheum jedoch gerettet werden. Nach umfassenden Renovierungen wurde es 1996 neu eröffnet, mit einem Schwerpunkt auf Kabarett, aber auch Konzerten und Kindertheateraufführungen"}, {"kategorie": "", "text": "Das Orpheum erlangte besondere Bekanntheit durch Auftritte internationaler Künstler wie R.E.M. und Bryan Adams, die dort Club-Konzerte gaben. Heute gilt es als bedeutende Bühne für Kabarett und Kleinkunst in Wien."}]'::jsonb, ''),
  ('freihofsiidlung', 'Freihofsiidlung', '', '', '', '', 'Freihofsiedlung', '[{"kategorie": "allg.", "text": "historische Gemeindesiedlung im 22. Wiener Gemeindebezirk ([[Donaustadt]])  im Bereich zwischen der [[Wagramer]] Straße, [[Am]] Freihof, der [[Rugierstraße]] und dem [[Kagraner]] Anger"}, {"kategorie": "", "text": "Die Siedlung wurde ursprünglich als Kleinhaussiedlung für Bedienstete von Versorgungsbetrieben wie dem E- und Gaswerk sowie der Straßenbahn zwischen 1923 und 1927 von Karl Schartelmüller im Auftrag des Wiener Siedlungsamtes erbaut"}, {"kategorie": "", "text": "Die Siedlung war als gartenstadtähnliche Verbauung des gesamten Stadtviertels konzipiert und begann mit 99 Häusern. Ab 1924 wurde sie in Zusammenarbeit mit den Siedlungsgenossenschaften „Mein Heim“, „Aus eigener Kraft“ und „Am Freihof“ erweitert, sodass bis zu 1.014 Wohnungen in 687 Einzelobjekten entstanden"}, {"kategorie": "", "text": "Damit wurde die Freihofsiedlung zu Wiens größter Siedlung dieser Art und war auch international von Bedeutung. Eine weitere geplante Erweiterung auf bis zu 2.200 Häuser wurde jedoch nie realisiert"}, {"kategorie": "", "text": "Die Freihofsiedlung gilt als markantes Beispiel für das Wiener Siedlungswesen der Zwischenkriegszeit und ist heute eine ruhige und gut erhaltene Wohngegend, die sich ihren gartenstadtähnlichen Charakter bewahrt hat."}]'::jsonb, ''),
  ('rugiaschdrossn', 'Rugiaschdrossn', '', '', '', '', 'Rugierstraße', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 22. Wiener Gemeindebezirk ([[Donaustadt]]) im Stadtteil [[Kagran]], einem der ältesten Teile des 22. Bezirks\""}, {"kategorie": "", "text": "Sie ist nach dem germanischen Volksstamm der Rugier benannt, die in der Spätantike und im frühen Mittelalter im heutigen Österreich und Böhmen ansässig waren. Die Rugier spielten eine bedeutende Rolle in der Völkerwanderungszeit und waren bekannt für ihre Kämpfe gegen das Römische Reich. Ihre historische Bedeutung spiegelt sich in der Benennung dieser Straße wider"}, {"kategorie": "", "text": "Die Rugierstraße liegt in einer Wohngegend, die historisch in Verbindung mit der Entwicklung von Siedlungsgebieten wie der [[Freihofsiedlung]] steht, welche in den 1920er Jahren entstand"}, {"kategorie": "", "text": "Heute ist die Rugierstraße Teil eines gut erschlossenen und ruhigen Wohngebiets in der [[Donaustadt]], das durch die Nähe zu Schulen, Grünflächen und öffentlichen Verkehrsmitteln geprägt ist."}]'::jsonb, ''),
  ('kaalteata', 'Kaalteata', '', '', '', '', 'Carltheater', '[{"kategorie": "allg.", "text": "\"eines der bedeutendsten Wiener Theater des 19. Jahrhunderts, welches sich in der [[Praterstraße]] 31 im 2. Wiener Gemeindebezirk befand (ursprünglich unter dem Namen \"Leopoldstädter Theater\" bekannt)\""}, {"kategorie": "", "text": "Es wurde 1781 von Karl Marinelli als Theater für Volksstücke, Singspiele und Possen gegründet, das vor allem durch die populären Figuren Kasperl und Staberl bekannt wurde. Zu den erfolgreichsten Autoren des Hauses zählten Carl Friedrich Hensler und Joachim Perinet. Marinellis Ensemble, darunter Schauspielgrößen wie Johann La Roche, trug maßgeblich zum Erfolg des Theaters bei"}, {"kategorie": "", "text": "Nach dem Tod Marinellis übernahm 1803 der Hausdichter Hensler die Leitung, gefolgt von Leopold Huber. Das Theater erlebte unter Hensler und später Ignaz Schuster als Darsteller des Staberl eine Blütezeit. Auch Ferdinand Raimund war ab 1828 sowohl Schauspieler als auch Direktor des Theaters, wo er seine berühmten Zauberspiele aufführte"}, {"kategorie": "", "text": "1837 übernahm Carl Carl, der Direktor des [[Theaters]] an der Wien, das Leopoldstädter Theater und leitete es zu neuem Glanz. Er ließ das alte Theater 1847 abreißen und nach Plänen von Eduard van der Nüll und August Sicard von Sicardsburg das prächtige Carltheater errichten. Es wurde am 10. Dezember 1847 eröffnet und entwickelte sich zu einer der führenden Bühnen Wiens. Unter Carls Leitung kamen zahlreiche Werke von Johann Nestroy zur Uraufführung, darunter der berühmte \"Lumpazivagabundus\""}, {"kategorie": "", "text": "Das Carltheater war auch ein wichtiger Schauplatz für die Entwicklung der Operette. Franz von Suppés Operette „Das Pensionat“ wurde hier 1860 uraufgeführt, womit das Haus einen weiteren Meilenstein in der Wiener Theatergeschichte setzte. Nach der Ära Carl führte Johann Nestroy das Theater von 1854 bis 1860, bevor es ab den 1870er Jahren von verschiedenen Direktoren geleitet wurde"}, {"kategorie": "", "text": "Trotz seines Erfolgs wurde das Carltheater 1929 geschlossen und fiel 1944 einem Bombenangriff zum Opfer. Die Ruine wurde 1951 endgültig abgerissen. An der Stelle des einst glanzvollen Theaters steht heute das Bürohochhaus \"Galaxie\", erbaut zwischen 1974 und 1978 nach Plänen von Josef Becvar und H. Neuroth."}]'::jsonb, ''),
  ('hofopa', 'Hofopa', '', '', '', '', 'Hofoper', '[{"kategorie": "allg.", "text": "eines der renommiertesten Opernhäuser der Welt (heute bekannt als [[Wiener]] Staatsoper)"}, {"kategorie": "", "text": "Sie wurde ursprünglich als kaiserliche Oper gegründet und diente während der Habsburger-Monarchie dem höfischen Publikum. Das Opernhaus wurde von 1861 bis 1869 an der Ringstraße im Stil der Neorenaissance nach Plänen von August Sicard von Sicardsburg und Eduard van der Nüll errichtet"}, {"kategorie": "", "text": "Die Wiener Hofoper war Teil des großen Bauprogramms auf der neuen Ringstraße. Die Eröffnung fand am 25. Mai 1869 mit Mozarts \"Don Giovanni\" unter Anwesenheit von Kaiser Franz Joseph und Kaiserin Elisabeth statt"}, {"kategorie": "", "text": "Ursprünglich hieß das Gebäude K.k. Hof-Opernhaus, es wurde aber ab 1920 als Staatsoper bezeichnet, nachdem die Monarchie zu Ende ging und Österreich zur Republik wurde"}, {"kategorie": "", "text": "Das ursprüngliche Gebäude stand anfangs unter Kritik, da es im Vergleich zu den benachbarten Prachtbauten zu \"schlicht\" erschien. Nach dem Selbstmord des Architekten van der Nüll und dem Tod Sicardsburgs wurde es dennoch eines der Wahrzeichen Wiens. Die Bombardierung im Zweiten Weltkrieg zerstörte das Gebäude schwer, aber die Hofoper wurde 1955 nach umfangreichen Wiederaufbauarbeiten wiedereröffnet."}]'::jsonb, ''),
  ('heandlwoid', 'Heandlwoid', '', '', '', '', 'Hörndlwald', '[{"kategorie": "allg.", "text": "\"etwa 56 Hektar großer Wald im 13. Wiener Gemeindebezirk ([[Hietzing]]), südlich von [[Ober-St]].-Veit\""}, {"kategorie": "", "text": "Der Wald gehört zu den beliebten Naherholungsgebieten der Stadt und war ursprünglich ein Teil des [[Lainzer]] Tiergartens. Nach dem [[Ersten]] Weltkrieg blieb der Hörndlwald bestehen, während andere Teile des Tiergartens, die außerhalb der Mauer lagen, abgeholzt wurden, um Platz für Siedlungsprojekte wie die [[Friedensstadt]], das Krankenhaus Lainz, die [[SAT-Siedlung]] und die [[Siedlung]] Lockerwiese zu schaffen"}, {"kategorie": "", "text": "Nach dem [[Zweiten]] Weltkrieg wurde der Hörndlwald durch die Volkshilfe, auf Initiative von Josef Afritsch und mit Unterstützung der schwedischen Sozialdemokraten, zu einem Erholungsgebiet ausgebaut. Diese Zusammenarbeit ermöglichte nicht nur die Schaffung von Erholungseinrichtungen, sondern auch die Durchführung von Großveranstaltungen und die Betreuung von Flüchtlingen. 1965 wurde das Gebiet zu Ehren von Afritsch in \"Josef-Afritsch-Heim\" umbenannt"}, {"kategorie": "", "text": "Der Hörndlwald war auch Schauplatz internationaler Veranstaltungen: 1952 fand hier das USY-Camp (International Union of Socialist Youth) der Sozialistischen Jugendinternationale statt, an dem 32.000 Teilnehmer aus 35 Ländern teilnahmen. 1958 folgte das Internationale Falkencamp. Der Pächter des Areals ist seit 1994 die Volkshilfe"}, {"kategorie": "", "text": "Heute dient der Hörndlwald vor allem als Naherholungsgebiet für Spaziergänger, Wanderer und Naturliebhaber und ist ein wichtiger Teil des Wiener Grüngürtels, der das ökologische Gleichgewicht der Stadt unterstützt."}]'::jsonb, ''),
  ('sillaplotz', 'Sillaplotz', '', '', '', '', 'Sillerplatz', '[{"kategorie": "allg.", "text": "\"kleiner Platz im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Stadtteil [[Mauer]]\""}, {"kategorie": "", "text": "Der Platz ist nach Franz Siller (*1893, †1924) benannt. Siller war eine bedeutende Persönlichkeit der Kleingartenbewegung in Österreich und diente als Präsident des Zentralverbandes der Kleingärtner, Siedler und Kleintierzüchter Österreichs. Er spielte eine zentrale Rolle bei der Förderung von Kleingärten als Mittel zur Selbstversorgung und sozialen Stabilisierung in den Jahren nach dem [[Ersten]] Weltkrieg"}, {"kategorie": "", "text": "Sillers Engagement brachte ihm zu Lebzeiten großen Respekt ein, weshalb ihm zu Ehren der Platz in Hietzing nach seinem frühen Tod im Jahr 1924 benannt wurde. Die Kleingartenbewegung hat in Wien bis heute eine wichtige Tradition, die eng mit dem Namen Franz Siller verbunden ist"}, {"kategorie": "", "text": "Heute ist der Sillerplatz in Hietzing ist ein relativ kleiner, ruhiger Platz, eingebettet in ein Wohngebiet. Er ist von Wohnhäusern umgeben und dient als kleiner, beschaulicher Erholungsort für die Anwohner."}]'::jsonb, ''),
  ('woikasbeagnschdrossn', 'Woikasbeagnschdrossn', '', '', '', '', 'Wolkersbergenstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), welche die beiden Stadtteile [[Lainz]] und [[Speising]] miteinander verbindet\""}, {"kategorie": "", "text": "Die Wolkersbergenstraße nimmt ihren Namen von einem historischen Riednamen („Wolkersbergen“), der auf alte landwirtschaftlich genutzte Flächen in der Region verweist"}, {"kategorie": "", "text": "Der Name „Wolkersbergen“ geht auf eine alte Bezeichnung für die nahegelegenen Hügel und Berge im Westen Wiens zurück. Laut einer alten Volksregel brachte das Wetterphänomen, bei dem Wolken über die Berge im Westen nach Osten zogen, häufig schlechtes Wetter mit sich. Diese Regel wurde von den Bewohnern der Region über Generationen hinweg tradiert und spiegelt das lokale Wissen über die Wetterverhältnisse wider. Daher leitet sich der Name der Straße von dieser Beobachtung ab, die dem Naturphänomen einen symbolischen Charakter verlieh"}, {"kategorie": "", "text": "Die Straße verläuft durch eine der ruhigeren Gegenden Wiens, in der sich zahlreiche Wohnsiedlungen und Einfamilienhäuser befinden. Sie ist außerdem durch ihre Nähe zur [[Siedlung]] Lockerwiese geprägt, einer bedeutenden Wohnsiedlung aus der Zwischenkriegszeit."}]'::jsonb, ''),
  ('camillianagossn', 'Camillianagossn', '', '', '', '', 'Camillianergasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Stadtteil [[Lainz]]\""}, {"kategorie": "", "text": "Sie ist nach dem katholischen Kamillianerorden (auch Camillianer genannt) benannt, einem im 16. Jahrhundert gegründeten Orden, dessen Mitglieder sich vor allem der Pflege von Kranken widmen. Der Orden geht auf den Heiligen Kamillus von Lellis zurück, der sich durch seinen Einsatz für Kranke und Bedürftige in Italien und Europa auszeichnete"}, {"kategorie": "", "text": "Die Camillianergasse liegt in einer ruhigen, vorwiegend von Wohnhäusern geprägten Gegend in Hietzing und ist Teil der Umgebung der [[Siedlung]] Lockerwiese. Diese Siedlung, die zwischen 1928 und 1938 errichtet wurde, ist eines der historischen Wohnbauprojekte in Wien, und die Camillianergasse führt durch diese Siedlung"}, {"kategorie": "", "text": "Die Straße zeichnet sich durch ihre ruhige Atmosphäre und die Nähe zu grünen Bereichen aus, die typisch für den Bezirk Hietzing sind, der für seine Parks und Villengegenden bekannt ist."}]'::jsonb, ''),
  ('englhartgossn', 'Englhartgossn', '', '', '', '', 'Engelhartgasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 13. Wiener Gemeindebezirk ([[Hietzing]]) im Stadtteil [[Lainz]]\""}, {"kategorie": "", "text": "Sie gehört zur [[Siedlung]] Lockerwiese und verläuft durch eine Gegend, die von zweigeschossigen Reihenhäusern geprägt ist, die zwischen 1928 und 1938 im Rahmen eines städtischen Wohnbauprogramms errichtet wurden"}, {"kategorie": "", "text": "Die Engelhartgasse ist nach dem bedeutenden österreichischen Maler und Bildhauer Josef Engelhart (*19. August 1864, †19. Dezember 1941) benannt. Engelhart war einer der Gründungsmitglieder der [[Wiener]] Secession, einer wegweisenden Künstlervereinigung, und prägte die Kunstszene Wiens maßgeblich"}, {"kategorie": "", "text": "Als Maler widmete er sich besonders wienerischen Themen und schuf Werke, die das alltägliche Leben und Volksleben der Stadt auf realistische Weise einfingen, insbesondere Szenen aus dem [[Prater]] und Alt-Wiener Typen. Zu seinen bekanntesten Gemälden zählen „Die Banda kummt“ und „Ein Pülcher“, die er 1888 in der Jubiläumsausstellung des [[Künstlerhauses]] zeigte."}]'::jsonb, ''),
  ('vasoagungsheimschdrossn', 'Vasoagungsheimschdrossn', '', '', '', '', 'Versorgungsheimstraße', '[{"kategorie": "allg.", "text": "ruhige Straße im 13. Wiener Gemeindebezirk (Hietzing), im Stadtteil [[Lainz]]"}, {"kategorie": "", "text": "Sie ist nach dem ehemaligen Versorgungsheim Lainz benannt wurde. Dieses Heim, auch als Lainzer Versorgungsheim (später \"Pflegeheim Lainz\") bekannt, war eine bedeutende soziale Einrichtung in Wien, die ursprünglich dazu diente, arme, alte und pflegebedürftige Menschen zu versorgen. Es wurde 1902 eröffnet und war eines der größten seiner Art in Europa"}, {"kategorie": "", "text": "Die Versorgungsheimstraße verweist auf die Geschichte der sozialen Fürsorge in Wien, die im ausgehenden 19. und frühen 20. Jahrhundert eine zentrale Rolle spielte. Das Lainzer Versorgungsheim (heute \"Geriatriezentrum am Wienerwald\") war ein Symbol für die städtischen Bemühungen, die Lebensbedingungen von älteren und bedürftigen Menschen zu verbessern. Es ist ein historischer Ort, der die Entwicklung des Wiener Gesundheitssystems und der Altenpflege im Kontext des [[Roten Wien]] verdeutlicht"}, {"kategorie": "", "text": "Heute verläuft die Versorgungsheimstraße durch ein ruhiges Wohngebiet in Hietzing und ist Teil jener Straßen, welche die [[Siedlung]] Lockerwiese umgeben. Diese Siedlung, die zwischen 1928 und 1938 errichtet wurde, besteht vorwiegend aus zweigeschossigen Reihenhäusern und ist ein bedeutendes Beispiel für den kommunalen Wohnbau der Zwischenkriegszeit"}, {"kategorie": "", "text": "Die Straße verbindet verschiedene Wohngebiete in Hietzing und liegt in der Nähe von weitläufigen Grünflächen wie dem [[Lainzer]] Tiergarten, einem beliebten Naherholungsgebiet in Wien."}]'::jsonb, ''),
  ('schdoakfriidgossn', 'Schdoakfriidgossn', '', '', '', '', 'Starkfriedgasse', '[{"kategorie": "allg.", "text": "\"Straße mit historischer Namensgebung im 18. Wiener Gemeindebezirk ([[Währing]]), im Stadtteil [[Pötzleinsdorf]]\""}, {"kategorie": "", "text": "Sie ist nach Starichfried von Pazelinesdorf benannt, einem Adligen, der im 12. Jahrhundert die Herrschaft über Pötzleinsdorf innehatte. Die Familie von Starichfried, auch bekannt als das Geschlecht Pazelinesdorf, spielte eine bedeutende Rolle in der frühen Geschichte dieser Region. Das Adelsgeschlecht wird bis ins 16. Jahrhundert in historischen Quellen erwähnt und hatte großen Einfluss auf die Entwicklung des Gebietes, das heute [[Pötzleinsdorf]] ist"}, {"kategorie": "", "text": "Die Starkfriedgasse verläuft durch das gehobene Wohngebiet von Pötzleinsdorf und ist vorwiegend von Villen und Wohnhäusern umgeben, die die exklusive Wohnlage widerspiegeln. In der Nähe befinden sich der [[Pötzleinsdorfer]] Schlosspark sowie der [[Pötzleinsdorfer]] Friedhof, was der Gegend ein besonders grünes und ruhiges Ambiente verleiht."}]'::jsonb, ''),
  ('notteboomschdrossn', 'Notteboomschdrossn', '', '', '', '', 'Nottebohmgasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 19. Wiener Gemeindebezirk ([[Döbling]]) im Stadtteil [[Sievering]]\""}, {"kategorie": "", "text": "Sie verläuft direkt am [[Sieveringer]] Friedhof  und ist nach dem Musikhistoriker Martin Gustav Nottebohm (1817–1882) benannt"}, {"kategorie": "", "text": "Nottebohm wurde am 12. November 1817 in Lüdenscheid, Nordrhein-Westfalen, geboren und war ein bedeutender Musikwissenschaftler und Komponist. Er studierte Musik in Berlin und Wien und ließ sich ab 1845 dauerhaft in Wien nieder, wo er als privater Musiklehrer arbeitete"}, {"kategorie": "", "text": "Nottebohm war eng mit Johannes Brahms befreundet und spielte eine wichtige Rolle im Wiener Musikleben. 1858 wurde er Mitglied der Direktion der Gesellschaft der Musikfreunde ([[Wiener]] Musikverein) und übernahm 1863 die Position des Archivars des Evangelischen Chorvereins Wien. Nottebohm trug wesentlich zur Musikwissenschaft bei, insbesondere durch seine Arbeiten über Beethoven. Er verstarb am 29. Oktober 1882 in Graz."}]'::jsonb, ''),
  ('hardeggossn', 'Hardeggossn', '', '', '', '', 'Hardeggasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 22. Wiener Gemeindebezirk ([[Donaustadt]]) im Stadtteil [[Stadlau]]\""}, {"kategorie": "", "text": "Die Straße ist nach drei Brüdern aus dem Grafengeschlecht Hardegg benannt, die sich in der [[Schlacht]] bei Aspern im Jahr 1809 besonders ausgezeichnet haben"}, {"kategorie": "", "text": "Die drei Brüder waren: (i) Johann Ignaz Hardegg (1772–1848), General der Kavallerie, (ii) Johann Anton Hardegg (1773–1825), Feldmarschalleutnant, und (iii) Johann Heinrich Hardegg (1778–1854), General der Kavallerie"}, {"kategorie": "", "text": "Die Hardeggasse führt durch eine verkehrsgünstige Wohngegend und bietet Zugang zum [[Stadlauer]] Friedhof, einem der historischen Friedhöfe Wiens"}, {"kategorie": "", "text": "Sie verbindet den Stadtteil Stadlau mit anderen Teilen der Donaustadt und hat durch ihre Lage in der Nähe von U-Bahn-Stationen und Einkaufsbereichen eine besondere Bedeutung für die Bewohner der Umgebung."}]'::jsonb, ''),
  ('heavicusgossn', 'Heavicusgossn', '', '', '', '', 'Hervicusgasse', '[{"kategorie": "allg.", "text": "\"kurze Gasse im 12. Wiener Gemeindebezirk ([[Meidling]]) im Stadtteil Hetzendorf\""}, {"kategorie": "", "text": "Die Gasse beginnt an der [[Hetzendorfer]] Straße und führt südwärts bis zum Haupteingang des [[Südwestfriedhofs]], wo sie an der [[Wundtgasse]] endet"}, {"kategorie": "", "text": "Im mittleren Teil der Hervicusgasse wird die Straße durch den [[Marschallplatz]] mit der markanten Rosenkranzkirche ([[Pfarrkirche]] Hetzendorf) unterbrochen, die ein dominantes Bauwerk in dieser Gegend darstellt"}, {"kategorie": "", "text": "Die Hervicusgasse  ist nach Hervicus von Hetzingen, einem fürstlichen Lehenbesitzer von Hetzendorf um das Jahr 1190, benannt. Vor ihrer Umbenennung trug sie den Namen Gärtnergasse"}, {"kategorie": "", "text": "Die Hervicusgasse verbindet wichtige Teile des Bezirks und bietet Zugang zum Südwestfriedhof, der zu den größten Friedhöfen Wiens zählt."}]'::jsonb, ''),
  ('marschallplotz', 'Marschallplotz', '', '', '', '', 'Marschallplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 12. Wiener Gemeindebezirk ([[Meidling]]) im Stadtteil [[Hetzendorf]]\""}, {"kategorie": "", "text": "Der Marschallplatz unterbricht die [[Hervicusgasse]], die von der [[Hetzendorfer]] Straße südwärts zum [[Südwestfriedhof]] führt und an der [[Wundtgasse]] endet"}, {"kategorie": "", "text": "Der Platz ist nach Bischof Godfried (Gottfried) Marschall benannt. Zuvor trug er den Namen Rosenkranzplatz, benannt nach der dort gelegenen großen Rosenkranzkirche ([[Pfarrkirche]] Hetzendorf), die den Platz dominiert"}, {"kategorie": "", "text": "Die Kirche ist ein markanter Blickfang und eine wichtige religiöse und architektonische Sehenswürdigkeit in diesem Teil des Bezirks."}]'::jsonb, ''),
  ('wundtgossn', 'Wundtgossn', '', '', '', '', 'Wundtgossn', '[{"kategorie": "allg.", "text": "\"Straße im 12. und 23. Wiener Gemeindebezirk ([[Meidling]] und [[Liesing]]), welche die Stadtteile [[Hetzendorf]] und [[Atzgersdorf]] miteinander verbindet\""}, {"kategorie": "", "text": "Die Gasse verläuft von der Unterführung der Südbahn bis zur Kreuzung [[Am]] Rosenhügel und ist nach dem deutschen Philosophen und Psychologen Wilhelm Wundt (1832–1920) benannt"}, {"kategorie": "", "text": "Wilhelm Wundt gilt als Begründer der modernen experimentellen Psychologie und gründete das erste Institut für experimentelle Psychologie an der Universität Leipzig. Zu seinen Hauptwerken gehört die zehnbändige \"Völkerpsychologie\" (1911–1920)"}, {"kategorie": "", "text": "Die Gasse war bis 1938 Teil der südlichen Stadtgrenze Wiens und ist heute teilweise Bezirksgrenze zwischen [[Meidling]] und [[Liesing]]. Wo sie beiderseits der Fahrbahn zum 12. Bezirk gehört, trennt sie den historischen Teil des [[Südwestfriedhofs]] von seinen im Süden angelegten neueren Erweiterungen. Die Gasse wird von der städtischen Autobuslinie 63A befahren."}]'::jsonb, ''),
  ('donaufoeoed', 'Donaufööd', '', '', '', '', 'Donaufeld', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 21. Wiener Bezirk ([[Floridsdorf]]), dessen Wurzeln in die Mitte des 19. Jahrhunderts zurückreichen\""}, {"kategorie": "", "text": "Gegründet zwischen 1860 und 1862, entwickelte sich das Gebiet schnell zu einer eigenständigen Ortsgemeinde. 1862 entstanden die ersten Häuser, und schon ein Jahr später zählte die Siedlung 30 Häuser und wurde \"Neu-Leopoldau\" genannt. Das enge wirtschaftliche und politische Verhältnis zu Leopoldau blieb bestehen, und die Bevölkerung wuchs rasch"}, {"kategorie": "", "text": "Mit der [[Donauregulierung]] 1875, bei der die [[Alte]] Donau vom Hauptstrom abgetrennt wurde, verloren die damals wichtigen Schiffsmühlen ihre Standplätze. 1881 wurden Neu-Leopoldau und das Gebiet [[Mühlschüttel]], das zuvor zur Gemeinde Alt-Leopoldau gehörte, eigenständig. Um Verwechslungen mit Alt-Leopoldau zu vermeiden, erhielt die Gemeinde 1885 den Namen Donaufeld. Unter der Leitung von Bürgermeister Franz Plankenbüchler wurden in dieser Zeit wichtige Infrastrukturen wie ein Kanalnetz und Gasbeleuchtung aufgebaut"}, {"kategorie": "", "text": "Mit 550 Häusern und 14.536 Einwohnern wurde Donaufeld 1894 gemeinsam mit Floridsdorf und anderen umliegenden Gemeinden zur Großgemeinde Floridsdorf zusammengelegt und 1905 in den neuen 21. Wiener Bezirk eingegliedert"}, {"kategorie": "", "text": "Heute spielt Donaufeld eine bedeutende Rolle als aufstrebendes Wohngebiet im 21. Bezirk. In den letzten Jahren hat sich der Stadtteil durch mehrere neue Wohnbauprojekte und urbane Entwicklungsmaßnahmen stark verändert. Insgesamt hat sich Donaufeld sohin von einem ehemals landwirtschaftlich geprägten Siedlungsgebiet zu einem modernen und dynamischen Stadtteil entwickelt."}]'::jsonb, ''),
  ('donaureguliirung', 'Donaureguliirung', '', '', '', '', 'Donauregulierung', '[{"kategorie": "allg.", "text": "\"Maßnahme zur Stabilisierung des Donauverlaufs und zur Gewährleistung des Hochwasserschutzes im Raum Wien\""}, {"kategorie": "", "text": "Ursprünglich aufgeteilt in zahlreiche Donauarme, führte die Donau regelmäßig zu schweren Überschwemmungen in den Vorstädten und umliegenden Gemeinden. Ziel der Regulierung war es, der Donau zwischen [[Nußdorf]] und [[Albern]] ein neues, gleichmäßiges Bett zu graben, um die Schifffahrt zu erleichtern und die Hochwassergefahr zu minimieren"}, {"kategorie": "", "text": "Der erste große Eingriff erfolgte zwischen 1870 und 1875, als ein neues Donaubett geschaffen wurde, das durch den [[Wiener Durchstich]] festgelegt wurde. Diese Baumaßnahme führte nicht nur zur Verbesserung des Hochwasserschutzes, sondern ermöglichte auch die urbane Entwicklung entlang der Donau. Ein Überschwemmungsgebiet am linken Ufer wurde geschaffen, um bei Hochwasser die Stadt zu schützen, während die entstehenden Landflächen für den Städtebau nutzbar wurden"}, {"kategorie": "", "text": "Nach der großen Überschwemmung von 1954 wurde 1972 das Projekt der zweiten Donauregulierung gestartet, das zur Schaffung der [[Donauinsel]] und der [[Neuen Donau]] führte, einem weiteren bedeutenden Hochwasserschutzprojekt."}]'::jsonb, ''),
  ('donaureguliirungskommission', 'Donaureguliirungskommission', '', '', '', '', 'Donauregulierungskommission', '[{"kategorie": "allg.", "text": "\"staatlich eingesetztes Gremium (als Instrument der öffentlichen Verwaltung), das am 13. Januar 1867 für die Planung und Durchführung der [[Donauregulierung]] eingerichtet wurde\""}, {"kategorie": "", "text": "Die Kommission setzte sich gleichberechtigt aus Vertretern des Staates, des [[Kronlands]] Niederösterreich und der Stadt Wien zusammen"}, {"kategorie": "", "text": "Ihre Hauptaufgabe bestand darin, den Bau eines neuen Donaubetts und den Hochwasserschutz zu organisieren, um die wiederkehrenden Überschwemmungen und deren Folgen für Wien und die umliegenden Gebiete zu verhindern"}, {"kategorie": "", "text": "Die Finanzierung der Regulierung, die rund 25 Millionen [[Gulden]] kostete, wurde zu je einem Drittel von Stadt, Land und Staat über Anleihen getragen. Die Kommission spielte eine zentrale Rolle bei der Realisierung des Projekts, das zu bedeutenden städtebaulichen Entwicklungen und einem verbesserten Hochwasserschutz führte"}, {"kategorie": "", "text": "1927 wurde die Kommission aufgelöst und von der Donauhochwasserschutz-Konkurrenz (DHK) abgelöst. Diese neue Organisation, heute von der Österreichischen Wasserstraßen-Gesellschaft \"via donau\" verwaltet, übernimmt Aufgaben wie die Erhaltung der Schutzbauten und Dämme, den Betrieb von Wehranlagen und Schleusen sowie die Verwaltung von Liegenschaften entlang der [[Donau]] und des [[Donaukanals]]."}]'::jsonb, ''),
  ('kronlaund', 'Kronlaund', '', '', '', '', 'Kronland', '[{"kategorie": "allg.", "text": "\"Verwaltungseinheit in der [[Habsburgermonarchie]] (auch [[Österreich-Ungarn]]), die direkt der Krone unterstellt war\""}, {"kategorie": "", "text": "Die Kronländer bildeten die einzelnen Territorien oder Länder, die zusammen das Reich der [[Habsburger]] bildeten. Jedes Kronland hatte eine gewisse Autonomie, jedoch unterlag es der zentralen Kontrolle des Kaisers oder der Monarchie"}, {"kategorie": "", "text": "Nach dem [[Österreichisch-Ungarischen]] Ausgleich von 1867 bestanden zwei große Reichsteile: die österreichischen Kronländer (in der sogenannten à„Cisleithanischen“ Reichshälfte) und die ungarischen Kronländer (in der à„Transleithanischen“ Reichshälfte). Beispiele für Kronländer in Cisleithanien waren Böhmen, Galizien, Kärnten und Niederösterreich"}, {"kategorie": "", "text": "Das Konzept des Kronlandes wurde nach dem Ende der Habsburgermonarchie 1918 mit dem Zerfall des Reichs und der Bildung neuer Nationalstaaten abgeschafft."}]'::jsonb, '')
